window.sourceCode = {"materiales/javascript/ahorrobucles/ahorro.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Mi reto de ahorro | JavaScript</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"app.js\" defer></script>\n</head>\n<body>\n\n  <main class=\"contenedor\">\n\n    <header class=\"cabecera\">\n      <span class=\"etiqueta\">PROYECTO JAVASCRIPT</span>\n      <h1>Mi reto de ahorro</h1>\n      \n<section class=\"tarjeta sobre-proyecto\">\n  <span class=\"seccion-etiqueta\">PROYECTO DE PORTFOLIO</span>\n\n  \n\n      <p>\n        Descubre cuántas semanas necesitas para\n        conseguir tu objetivo.\n      </p>\n    </header>\n\n    <section class=\"tarjeta\">\n      <h2>Configura tu objetivo</h2>\n\n      <div class=\"formulario\">\n\n        <div class=\"campo\">\n          <label for=\"inicial\">\n            ¿Cuánto dinero tienes ahora?\n          </label>\n          <input\n            type=\"number\"\n            id=\"inicial\"\n            value=\"40\"\n            min=\"0\"\n            step=\"0.01\"\n          >\n        </div>\n\n        <div class=\"campo\">\n          <label for=\"semanal\">\n            ¿Cuánto ahorrarás cada semana?\n          </label>\n          <input\n            type=\"number\"\n            id=\"semanal\"\n            value=\"15\"\n            min=\"0.01\"\n            step=\"0.01\"\n          >\n        </div>\n\n        <div class=\"campo\">\n          <label for=\"objetivo\">\n            ¿Cuánto dinero necesitas?\n          </label>\n          <input\n            type=\"number\"\n            id=\"objetivo\"\n            value=\"250\"\n            min=\"0.01\"\n            step=\"0.01\"\n          >\n        </div>\n\n        <div class=\"campo\">\n          <label for=\"maxSemanas\">\n            ¿Cuántas semanas tienes como máximo?\n          </label>\n          <input\n            type=\"number\"\n            id=\"maxSemanas\"\n            value=\"20\"\n            min=\"1\"\n            max=\"520\"\n            step=\"1\"\n          >\n        </div>\n\n        <button\n          type=\"button\"\n          onclick=\"calcularAhorro()\"\n        >\n          Calcular mi ahorro\n        </button>\n\n      </div>\n    </section>\n\n    <section class=\"tarjeta resultados\">\n      <h2>Resultado de tu simulación</h2>\n\n      <p id=\"resultado\" class=\"mensaje\">\n        Introduce los datos y pulsa el botón.\n      </p>\n\n      <div class=\"resumen\">\n        <div class=\"dato\">\n          <span>Semanas utilizadas</span>\n          <strong id=\"semanasResultado\">—</strong>\n        </div>\n\n        <div class=\"dato\">\n          <span>Dinero conseguido</span>\n          <strong id=\"totalResultado\">—</strong>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"tarjeta\">\n      <h2>Tu ahorro semana a semana</h2>\n      <p class=\"descripcion\">\n        Aquí aparecerá la evolución de tu dinero.\n      </p>\n\n      <pre id=\"historial\" class=\"historial\">Todavía no hay datos.</pre>\n    </section>\n\n<section class=\"tarjeta sobre-proyecto\">\n\n  <h2>Sobre este proyecto</h2>\n\n  <p class=\"descripcion-proyecto\">\n    He desarrollado un simulador de ahorro que permite\n    calcular cuántas semanas necesito para alcanzar\n    un objetivo económico. La aplicación recibe los\n    datos del usuario, realiza los cálculos y muestra\n    la evolución del ahorro semana a semana.\n  </p>\n\n  <p class=\"descripcion-proyecto\">\n    Durante su desarrollo he practicado\n    <strong>variables, operadores, condicionales y bucles</strong>.\n    También he aprendido a utilizar contadores y\n    acumuladores para realizar cálculos, y a mostrar\n    resultados dinámicamente mediante JavaScript.\n  </p>\n\n  <div class=\"tecnologias\">\n    <span>HTML5</span>\n    <span>CSS3</span>\n    <span>JavaScript</span>\n    <span>Bucles</span>\n    <span>Condicionales</span>\n  </div>\n\n</section>\n\n\n    <footer>\n      Práctica integradora de JavaScript · Bucles\n    </footer>\n\n  </main>\n\n</body>\n</html>\n","materiales/javascript/ahorrobucles/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/*\n=====================================================\n  SOLUCIÓN DEL PROFESOR\n  PRÁCTICA: MI RETO DE AHORRO\n=====================================================\n*/\n\nfunction calcularAhorro() {\n\n  // 1. OBTENER DATOS\n\n  const inicialTexto =\n    document.getElementById(\"inicial\").value;\n\n  const semanalTexto =\n    document.getElementById(\"semanal\").value;\n\n  const objetivoTexto =\n    document.getElementById(\"objetivo\").value;\n\n  const maxSemanasTexto =\n    document.getElementById(\"maxSemanas\").value;\n\n  const inicial = Number(inicialTexto);\n  const semanal = Number(semanalTexto);\n  const objetivo = Number(objetivoTexto);\n  const maxSemanas = Number(maxSemanasTexto);\n\n\n  // 2. VALIDAR DATOS\n\n  if (\n    inicialTexto.trim() === \"\" ||\n    semanalTexto.trim() === \"\" ||\n    objetivoTexto.trim() === \"\" ||\n    maxSemanasTexto.trim() === \"\" ||\n    !Number.isFinite(inicial) ||\n    !Number.isFinite(semanal) ||\n    !Number.isFinite(objetivo) ||\n    !Number.isInteger(maxSemanas) ||\n    inicial < 0 ||\n    semanal <= 0 ||\n    objetivo <= 0 ||\n    maxSemanas < 1 ||\n    maxSemanas > 520\n  ) {\n    document.getElementById(\"resultado\").textContent =\n      \"Revisa los datos introducidos.\";\n\n    document.getElementById(\"semanasResultado\").textContent = \"—\";\n    document.getElementById(\"totalResultado\").textContent = \"—\";\n    document.getElementById(\"historial\").textContent = \"\";\n\n    return;\n  }\n\n\n  // 3. VARIABLES\n\n  let total = inicial;\n  let semanas = 0;\n  let historial = \"\";\n  let mensaje = \"\";\n\n\n  // =====================================\n  // SOLUCIÓN MISIÓN 1: WHILE\n  // =====================================\n\n  /*\n  El bucle continúa mientras se cumplan\n  las dos condiciones:\n\n  1. Todavía no tenemos suficiente dinero.\n  2. No hemos agotado las semanas disponibles.\n\n  total es un ACUMULADOR.\n  semanas es un CONTADOR.\n  */\n\n  while (total < objetivo && semanas < maxSemanas) {\n\n    // Añadir el ahorro semanal\n    total += semanal;\n\n    // Contar una semana más\n    semanas++;\n\n  }\n\n\n  // =====================================\n  // SOLUCIÓN MISIÓN 2: IF / ELSE\n  // =====================================\n\n  if (total >= objetivo) {\n\n    mensaje = \"¡Objetivo conseguido!\";\n\n  } else {\n\n    mensaje = \"No has alcanzado tu objetivo.\";\n\n  }\n\n\n  // =====================================\n  // SOLUCIÓN MISIÓN 3: FOR\n  // =====================================\n\n  /*\n  Reconstruimos el historial desde el\n  dinero inicial.\n\n  El FOR se repite exactamente el número\n  de semanas que calculamos con WHILE.\n  */\n\n  let ahorroHistorial = inicial;\n\n  if (semanas === 0) {\n\n    historial = \"El objetivo ya estaba conseguido.\";\n\n  } else {\n\n    for (let i = 1; i <= semanas; i++) {\n\n      ahorroHistorial += semanal;\n\n      historial +=\n        \"Semana \" + i + \": \" +\n        ahorroHistorial.toFixed(2) + \" €\\n\";\n\n    }\n\n  }\n\n\n  // =====================================\n  // 4. MOSTRAR RESULTADOS\n  // =====================================\n\n  document.getElementById(\"resultado\").textContent =\n    mensaje;\n\n  document.getElementById(\"semanasResultado\").textContent =\n    semanas;\n\n  document.getElementById(\"totalResultado\").textContent =\n    total.toFixed(2) + \" €\";\n\n  document.getElementById(\"historial\").textContent =\n    historial;\n\n}\n\r\n","materiales/javascript/ahorrobucles/styles.css":"\n/* =====================================\n   MI RETO DE AHORRO\n   CSS sencillo para portfolio\n===================================== */\n\n:root {\n  --primario: #2563eb;\n  --fondo: #f1f5f9;\n  --blanco: #ffffff;\n  --texto: #263238;\n  --gris: #64748b;\n  --borde: #e2e8f0;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: 30px 15px;\n  font-family: Arial, sans-serif;\n  background-color: var(--fondo);\n  color: var(--texto);\n  line-height: 1.6;\n}\n\n.contenedor {\n  max-width: 760px;\n  margin: auto;\n}\n\n/* CABECERA */\n\n.cabecera {\n  text-align: center;\n  margin-bottom: 30px;\n}\n\n.etiqueta {\n  display: inline-block;\n  background-color: #fef3c7;\n  color: #92400e;\n  padding: 6px 14px;\n  border-radius: 20px;\n  font-size: 12px;\n  font-weight: bold;\n}\n\nh1 {\n  font-size: 36px;\n  margin: 15px 0 10px;\n}\n\n.cabecera p {\n  color: var(--gris);\n}\n\n/* TARJETAS */\n\n.tarjeta {\n  background-color: var(--blanco);\n  padding: 25px;\n  margin-bottom: 20px;\n  border: 1px solid var(--borde);\n  border-radius: 12px;\n}\n\nh2 {\n  margin-top: 0;\n  font-size: 22px;\n}\n\n/* FORMULARIO */\n\n.formulario {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 18px;\n}\n\n.campo {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\nlabel {\n  font-weight: bold;\n  font-size: 14px;\n}\n\ninput {\n  width: 100%;\n  padding: 12px;\n  border: 1px solid #cbd5e1;\n  border-radius: 8px;\n  font-size: 16px;\n}\n\ninput:focus {\n  outline: 2px solid var(--primario);\n  outline-offset: 2px;\n}\n\nbutton {\n  grid-column: 1 / -1;\n  padding: 14px;\n  background-color: var(--primario);\n  color: white;\n  border: none;\n  border-radius: 8px;\n  font-size: 16px;\n  cursor: pointer;\n}\n\nbutton:hover {\n  background-color: #1d4ed8;\n}\n\nbutton:focus-visible {\n  outline: 3px solid #f59e0b;\n  outline-offset: 3px;\n}\n\n/* RESULTADOS */\n\n.mensaje {\n  background-color: #eff6ff;\n  padding: 15px;\n  border-radius: 8px;\n  color: #1e40af;\n  font-weight: bold;\n}\n\n.resumen {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 15px;\n  margin-top: 20px;\n}\n\n.dato {\n  background-color: var(--fondo);\n  padding: 18px;\n  border-radius: 8px;\n  text-align: center;\n}\n\n.dato span {\n  display: block;\n  color: var(--gris);\n  font-size: 13px;\n}\n\n.dato strong {\n  display: block;\n  font-size: 28px;\n  color: var(--primario);\n}\n\n/* HISTORIAL */\n\n.descripcion {\n  color: var(--gris);\n  font-size: 14px;\n}\n\n.historial {\n  background-color: #0f172a;\n  color: white;\n  padding: 20px;\n  border-radius: 8px;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  line-height: 1.8;\n  font-size: 14px;\n}\n\n/* SECCIÓN SOBRE EL PROYECTO */\n\n.sobre-proyecto {\n  text-align: center;\n  background-color: #eff6ff;\n}\n\n.sobre-proyecto h2 {\n  color: var(--primario);\n}\n\n.descripcion-proyecto {\n  max-width: 620px;\n  margin: 0 auto 15px;\n  font-size: 15px;\n}\n\n.tecnologias {\n  display: flex;\n  justify-content: center;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 20px;\n}\n\n.tecnologias span {\n  background-color: var(--blanco);\n  color: var(--primario);\n  border: 1px solid #bfdbfe;\n  border-radius: 20px;\n  padding: 6px 12px;\n  font-size: 12px;\n  font-weight: bold;\n}\n\n/* PIE */\n\nfooter {\n  text-align: center;\n  color: var(--gris);\n  font-size: 13px;\n  margin-top: 30px;\n}\n\n/* RESPONSIVE */\n\n@media (max-width: 600px) {\n  .formulario,\n  .resumen {\n    grid-template-columns: 1fr;\n  }\n\n  h1 {\n    font-size: 28px;\n  }\n\n  .tarjeta {\n    padding: 20px;\n  }\n}\n","materiales/javascript/arrays/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nconst alumnos = [\"Ana\", \"Luis\", \"Marta\"];\n\nfor (let i = 0; i < alumnos.length; i++) {\n  console.log(alumnos[i]);\n}\r\n","materiales/javascript/arrays/arrays.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Aprendiendo arrays</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    \n</body>\n</html>","materiales/javascript/arrays/styles.css":"","materiales/javascript/cartas/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nlet puntosJugador = 0;\nlet puntosBanca = 0;\nlet partidaActiva = true;\n\n// Pide una carta para el jugador y actualiza sus puntos.\nfunction pedirCarta() {\n  if (!partidaActiva) {\n    return;\n  }\n\n  const carta = Math.floor(Math.random() * 10) + 1;\n  let valor;\n  if (carta <= 7) {\n    valor = carta;\n  } else {\n    valor = 0.5;\n  }\n\n  puntosJugador += valor;\n  document.getElementById(\"cartaJugador\").textContent = \"Tu última carta: \" + carta;\n  document.getElementById(\"puntosJugador\").textContent = \"Tus puntos: \" + puntosJugador;\n\n  if (puntosJugador > 7.5) {\n    plantarse();\n  }\n}\n\n\n\n// Da una única carta a la banca y termina la partida.\nfunction plantarse() {\n  if (!partidaActiva) {\n    return;\n  }\n\n  const carta = Math.floor(Math.random() * 10) + 1;\n  let valor;\n  if (carta <= 7) {\n    valor = carta;\n  } else {\n    valor = 0.5;\n  }\n\n  puntosBanca = valor;\n  document.getElementById(\"cartaBanca\").textContent = \"Carta de la banca: \" + carta;\n  document.getElementById(\"puntosBanca\").textContent = \"Puntos de la banca: \" + puntosBanca;\n  const mensaje = comprobarGanador(puntosJugador, puntosBanca);\n  document.getElementById(\"resultado\").textContent = mensaje;\n\n  partidaActiva = false;\n}\n\n// Reinicia los datos de la partida actual.\nfunction nuevaPartida() {\n  puntosJugador = 0;\n  puntosBanca = 0;\n  partidaActiva = true;\n  document.getElementById(\"cartaJugador\").textContent = \"Tu última carta: —\";\n  document.getElementById(\"puntosJugador\").textContent = \"Tus puntos: 0\";\n  document.getElementById(\"cartaBanca\").textContent = \"Carta de la banca: —\";\n  document.getElementById(\"puntosBanca\").textContent = \"Puntos de la banca: 0\";\n  document.getElementById(\"resultado\").textContent = \"Nueva partida preparada.\";\n}\r\n","materiales/javascript/cartas/cartas.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Jugando a las 7.30</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <main class=\"juego\">\n  <h1>Juego de las siete y media</h1>\n  <p id=\"cartaJugador\">Tu última carta: </p>\n  <p id=\"puntosJugador\" class=\"puntuacion\">Tus puntos: 0</p>\n  <p id=\"cartaBanca\">Carta de la banca: —</p>\n  <p id=\"puntosBanca\" class=\"puntuacion\">Puntos de la banca: 0</p>\n  <p id=\"resultado\">La partida está preparada.</p>\n  <button onclick=\"pedirCarta()\">Pedir carta</button>\n  <button onclick=\"plantarse()\">Plantarse</button>\n  <button onclick=\"nuevaPartida()\">Nueva partida</button>\n</main>\n</body>\n</html>","materiales/javascript/cartas/styles.css":"body {\n  background-color: #f3f0e6;\n  color: #1e2a20;\n  font-family: Arial, sans-serif;\n  margin: 0;\n  padding: 24px;\n  text-align: center;\n}\n.juego {\n  background-color: #0d4a32;\n  border: 4px solid #d7b85b;\n  border-radius: 16px;\n  color: white;\n  margin: 0 auto;\n  max-width: 620px;\n  padding: 24px;\n}\n.puntuacion,\n.contador,\n#resultado {\n  background-color: #ffffff;\n  border-radius: 8px;\n  color: #1e2a20;\n  margin: 12px 0;\n  padding: 12px;\n}\nbutton {\n  border: 0;\n  border-radius: 6px;\n  cursor: pointer;\n  font-family: Arial, sans-serif;\n  margin: 6px;\n  padding: 10px 14px;\n}\n.pedir {\n  background-color: #f4d35e;\n}\n.plantar {\n  background-color: #f39c6b;\n}\n.nueva {\n  background-color: #b9e3c6;\n}\nbutton:hover {\n  background-color: #ffffff;\n}\n","materiales/javascript/citaActividad/app.js":"","materiales/javascript/citaActividad/index.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title></title>\n\n <link rel=\"stylesheet\" href=\"styles.css\">\n <script src=\"app.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- CABECERA -->\n  <header class=\"cabecera\">\n    <div class=\"contenedor contenido-cabecera\">\n\n      <div class=\"marca\">\n        <span>✂ Mi peluquería</span>\n        <span class=\"icono-marca\">💇‍♀️</span>\n      </div>\n\n      <img\n        class=\"imagen-peluqueria\"\n        src=\"images/imagenPeluqueria.png\"\n        alt=\"Ilustración de una peluquería\"\n      >\n\n    </div>\n  </header>\n\n\n  <main class=\"contenedor\">\n\n    <!-- INTRODUCCIÓN -->\n    <div class=\"introduccion\">\n      <h1>Gestor de citas</h1>\n      <p>\n        Registra los servicios de tus clientes\n        y administra las citas de tu peluquería.\n      </p>\n    </div>\n\n    <h2>Los consejos de tu peluquero</h2>\n    <!-- BOTONES INFORMATIVOS -->\n\n    <div class=\"distribucion\">\n\n      <!-- ========================= -->\n      <!-- FORMULARIO DE NUEVA CITA -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>1. Nueva cita</h2>\n        <p>Introduce los datos del cliente.</p>\n\n        <form id=\"formularioCita\">\n\n          <!-- NOMBRE -->\n          <div class=\"campo\">\n            <label for=\"nombreCliente\">\n              Nombre del cliente\n            </label>\n\n            <input\n              id=\"nombreCliente\"\n              type=\"text\"\n              placeholder=\"Ej.: Marta Ruiz\"\n            \n            >\n          </div>\n\n          <!-- SERVICIO -->\n          <div class=\"campo\">\n            <label for=\"servicio\">\n              Servicio\n            </label>\n\n            <select id=\"servicio\" >\n              <option value=\"\">\n                Selecciona un servicio\n              </option>\n              <option value=\"Corte\">Corte</option>\n              <option value=\"Peinado\">Peinado</option>\n              <option value=\"Tinte\">Tinte</option>\n              <option value=\"Barba\">Barba</option>\n              <option value=\"Corte y peinado\">\n                Corte y peinado\n              </option>\n            </select>\n          </div>\n\n          <!-- PRECIO -->\n          <div class=\"campo\">\n            <label for=\"precio\">\n              Precio (€)\n            </label>\n\n            <input\n              id=\"precio\"\n              type=\"number\"\n              step=\"0.01\"\n              placeholder=\"Ej.: 25\"\n              \n            >\n          </div>\n\n          <!-- BOTÓN DE ENVÍO -->\n          <button\n            type=\"submit\"\n            class=\"boton-principal\"\n            onclick=\"agregarCita()\"\n          >\n            Añadir cita →\n          </button>\n\n          <p id=\"mensaje\" class=\"mensaje\"></p>\n\n        </form>\n\n      </section>\n\n\n      <!-- ========================= -->\n      <!-- LISTADO DE CITAS -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>2. Citas registradas</h2>\n        <p>Listado de servicios realizados.</p>\n\n        <p class=\"contador\">\n          Total de citas:\n          <span id=\"totalCitas\">0</span>\n        </p>\n\n        <!-- JavaScript creará aquí las tarjetas -->\n        <div\n          id=\"listaCitas\"\n          class=\"lista-citas\"\n        ></div>\n\n\n        <!-- IMPORTE TOTAL -->\n        <div class=\"resumen-total\">\n\n          <h3>Importe total de las citas</h3>\n\n          <p id=\"importeTotal\">0 €</p>\n\n        </div>\n\n      </section>\n\n    </div>\n\n\n    <!-- ========================= -->\n    <!-- ESPACIO PARA EL RETO 4 -->\n    <!-- ========================= -->\n\n    <!--\n      Aquí crearás una nueva sección\n      con dos botones:\n\n      - Servicio de la semana\n      - Consejo de peluquería\n\n      Añade también un párrafo donde\n      mostrarás los mensajes.\n    -->\n\n\n    <!-- IMAGEN DE DESPEDIDA -->\n    <img\n      class=\"imagen-gracias\"\n      src=\"images/gracias.png\"\n      alt=\"Mensaje de agradecimiento por el curso de desarrollo web\"\n    >\n\n  </main>\n\n\n  <!-- PIE DE PÁGINA -->\n  <footer class=\"pie-pagina\">\n    Práctica final · HTML + CSS + JavaScript\n  </footer>\n\n</body>\n</html>\n","materiales/javascript/citaActividad/solucion.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title></title>\n\n <link rel=\"stylesheet\" href=\"styles.css\">\n <script src=\"solucion.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- CABECERA -->\n  <header class=\"cabecera\">\n    <div class=\"contenedor contenido-cabecera\">\n\n      <div class=\"marca\">\n        <span>✂ Mi peluquería</span>\n        <span class=\"icono-marca\">💇‍♀️</span>\n      </div>\n\n      <img\n        class=\"imagen-peluqueria\"\n        src=\"images/imagenPeluqueria.png\"\n        alt=\"Ilustración de una peluquería\"\n      >\n\n    </div>\n  </header>\n\n\n  <main class=\"contenedor\">\n\n    <!-- INTRODUCCIÓN -->\n    <div class=\"introduccion\">\n      <h1>Gestor de citas</h1>\n      <p>\n        Registra los servicios de tus clientes\n        y administra las citas de tu peluquería.\n      </p>\n    </div>\n\n    <h2>Los consejos de tu peluquero</h2>\n    <!-- BOTONES INFORMATIVOS -->\n\n    <div class=\"distribucion\">\n\n      <!-- ========================= -->\n      <!-- FORMULARIO DE NUEVA CITA -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>1. Nueva cita</h2>\n        <p>Introduce los datos del cliente.</p>\n\n        <form id=\"formularioCita\">\n\n          <!-- NOMBRE -->\n          <div class=\"campo\">\n            <label for=\"nombreCliente\">\n              Nombre del cliente\n            </label>\n\n            <input\n              id=\"nombreCliente\"\n              type=\"text\"\n              placeholder=\"Ej.: Marta Ruiz\"\n            \n            >\n          </div>\n\n          <!-- SERVICIO -->\n          <div class=\"campo\">\n            <label for=\"servicio\">\n              Servicio\n            </label>\n\n            <select id=\"servicio\" >\n              <option value=\"\">\n                Selecciona un servicio\n              </option>\n              <option value=\"Corte\">Corte</option>\n              <option value=\"Peinado\">Peinado</option>\n              <option value=\"Tinte\">Tinte</option>\n              <option value=\"Barba\">Barba</option>\n              <option value=\"Corte y peinado\">\n                Corte y peinado\n              </option>\n            </select>\n          </div>\n\n          <!-- PRECIO -->\n          <div class=\"campo\">\n            <label for=\"precio\">\n              Precio (€)\n            </label>\n\n            <input\n              id=\"precio\"\n              type=\"number\"\n              step=\"0.01\"\n              placeholder=\"Ej.: 25\"\n              \n            >\n          </div>\n\n          <!-- BOTÓN DE ENVÍO -->\n          <button\n            type=\"button\"\n            class=\"boton-principal\"\n            onclick=\"agregarCita()\"\n          >\n            Añadir cita →\n          </button>\n\n          <p id=\"mensaje\" class=\"mensaje\"></p>\n\n        </form>\n\n      </section>\n\n\n      <!-- ========================= -->\n      <!-- LISTADO DE CITAS -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>2. Citas registradas</h2>\n        <p>Listado de servicios realizados.</p>\n\n        <p class=\"contador\">\n          Total de citas:\n          <span id=\"totalCitas\">0</span>\n        </p>\n\n        <!-- JavaScript creará aquí las tarjetas -->\n        <div\n          id=\"listaCitas\"\n          class=\"lista-citas\"\n        ></div>\n\n\n        <!-- IMPORTE TOTAL -->\n        <div class=\"resumen-total\">\n\n          <h3>Importe total de las citas</h3>\n\n          <p id=\"importeTotal\">0 €</p>\n\n        </div>\n\n      </section>\n\n    </div>\n\n\n    <!-- ========================= -->\n    <!-- ESPACIO PARA EL RETO 4 -->\n    <!-- ========================= -->\n\n    <!--\n      Aquí crearás una nueva sección\n      con dos botones:\n\n      - Servicio de la semana\n      - Consejo de peluquería\n\n      Añade también un párrafo donde\n      mostrarás los mensajes.\n    -->\n\n\n    <!-- IMAGEN DE DESPEDIDA -->\n    <img\n      class=\"imagen-gracias\"\n      src=\"images/gracias.png\"\n      alt=\"Mensaje de agradecimiento por el curso de desarrollo web\"\n    >\n\n  </main>\n\n\n  <!-- PIE DE PÁGINA -->\n  <footer class=\"pie-pagina\">\n    Práctica final · HTML + CSS + JavaScript\n  </footer>\n\n</body>\n</html>\n\r\n","materiales/javascript/citaActividad/solucion.js":"/*\n * SOLUCIÓN RECONSTRUIDA · ACTIVIDAD GESTOR DE CITAS\n *\n * La plantilla mantiene app.js vacío para que puedas realizar la actividad.\n * Esta solución usa los identificadores que ya existen en index.html.\n * Al añadir una cita: leemos los inputs, creamos un objeto, hacemos push()\n * y volvemos a pintar el listado para que DOM y array estén sincronizados.\n */\n\nlet citas = [\n  { cliente: \"Marta Ruiz\", servicio: \"Corte\", precio: 25 },\n  { cliente: \"Juan Pérez\", servicio: \"Peinado\", precio: 30 }\n];\n\nconst listaCitas = document.getElementById(\"listaCitas\");\nconst totalCitas = document.getElementById(\"totalCitas\");\nconst importeTotal = document.getElementById(\"importeTotal\");\nconst formulario = document.getElementById(\"formularioCita\");\nconst nombreCliente = document.getElementById(\"nombreCliente\");\nconst servicio = document.getElementById(\"servicio\");\nconst precio = document.getElementById(\"precio\");\nconst mensaje = document.getElementById(\"mensaje\");\n\n// Recorre el array y crea una tarjeta por cada cita registrada.\nfunction mostrarCitas() {\n  listaCitas.innerHTML = \"\";\n  let total = 0;\n\n  for (const cita of citas) {\n    listaCitas.innerHTML += `\n      <article class=\"cita\">\n        <h3>${cita.cliente}</h3>\n        <p>${cita.servicio}</p>\n        <p class=\"precio\">${cita.precio} €</p>\n      </article>\n    `;\n    total += cita.precio;\n  }\n\n  totalCitas.textContent = citas.length;\n  importeTotal.textContent = total + \" €\";\n}\n\n// Lee los datos del formulario y añade una nueva cita al array.\nfunction agregarCita() {\n  const nuevaCita = {\n    cliente: nombreCliente.value.trim(),\n    servicio: servicio.value,\n    precio: Number(precio.value)\n  };\n\n  if (!nuevaCita.cliente || !nuevaCita.servicio || nuevaCita.precio <= 0) {\n    mensaje.textContent = \"Completa los datos de la cita.\";\n    return;\n  }\n\n  citas.push(nuevaCita);\n  formulario.reset();\n  mensaje.textContent = \"Cita añadida correctamente.\";\n  mostrarCitas();\n}\n\nmostrarCitas();\r\n","materiales/javascript/citaActividad/styles.css":"\n/* =====================================\n   ESTILOS GENERALES\n===================================== */\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background-color: #f6f4f2;\n  color: #333;\n}\n\n.contenedor {\n  max-width: 1100px;\n  margin: auto;\n  padding: 20px;\n}\n\nh1, h2, h3 {\n  color: #914f57;\n}\n\n\n/* =====================================\n   CABECERA\n===================================== */\n\n.cabecera {\n  background-color: white;\n}\n\n.contenido-cabecera {\n  display: flex;\n  align-items: center;\n  gap: 30px;\n}\n\n.marca {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  font-size: 28px;\n  font-weight: bold;\n  color: #c00d8a;\n  text-align: center;\n}\n\n.icono-marca {\n  font-size: 60px;\n}\n\n.imagen-peluqueria {\n  width: 65%;\n  height: 220px;\n  object-fit: cover;\n  border-radius: 10px;\n}\n\n\n/* =====================================\n   INTRODUCCIÓN\n===================================== */\n\n.introduccion {\n  margin: 20px 0 30px;\n}\n\n\n/* =====================================\n   DISTRIBUCIÓN PRINCIPAL\n===================================== */\n\n.distribucion {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n}\n\n.panel {\n  background-color: white;\n  padding: 25px;\n  border-radius: 10px;\n}\n\n\n/* =====================================\n   CAMPOS DEL FORMULARIO\n===================================== */\n\n.campo {\n  margin-bottom: 20px;\n}\n\nlabel {\n  display: block;\n  margin-bottom: 5px;\n  font-weight: bold;\n}\n\ninput,\nselect {\n  width: 100%;\n  padding: 10px;\n  border: 1px solid #ccc;\n  border-radius: 5px;\n}\n\n\n/* =====================================\n   BOTÓN\n===================================== */\n\n.boton-principal {\n  width: 100%;\n  padding: 12px;\n  background-color: #c00d8a;\n  color: white;\n  border: none;\n  border-radius: 5px;\n  cursor: pointer;\n}\n\n.boton-principal:hover {\n  background-color: #914f57;\n}\n\n.mensaje {\n  color: #f109bb;\n  font-weight: bold;\n  font-size: 16px;\n}\n\n/* =====================================\n   CITAS REGISTRADAS\n===================================== */\n\n.lista-citas {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.cita {\n  background-color: #f6f4f2;\n  padding: 15px;\n  border-radius: 8px;\n}\n\n.cita h3 {\n  margin: 0 0 5px;\n}\n\n.cita p {\n  margin: 5px 0;\n}\n\n.precio {\n  color: #c00d8a;\n  font-weight: bold;\n}\n\n.contador {\n  font-weight: bold;\n}\n\n\n/* =====================================\n   IMPORTE TOTAL\n===================================== */\n\n.resumen-total {\n  background-color: #f4e4e5;\n  padding: 15px;\n  margin-top: 20px;\n  border-radius: 8px;\n  text-align: center;\n}\n\n#importeTotal {\n  font-size: 25px;\n  font-weight: bold;\n  color: #c00d8a;\n}\n\n\n/* =====================================\n   IMAGEN FINAL Y PIE\n===================================== */\n\n.imagen-gracias {\n  display: block;\n  width: 100%;\n  margin: 30px auto;\n  border-radius: 10px;\n}\n\n.pie-pagina {\n  text-align: center;\n  padding: 20px;\n  background-color: white;\n  color: #666;\n}\n\n\n/* =====================================\n   ADAPTACIÓN A MÓVILES\n===================================== */\n\n@media (max-width: 750px) {\n\n  .distribucion {\n    grid-template-columns: 1fr;\n  }\n\n  .contenido-cabecera {\n    flex-direction: column;\n  }\n\n  .imagen-peluqueria {\n    width: 100%;\n  }\n\n}\n","materiales/javascript/citas/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/*\n  PRÁCTICA FINAL · GESTOR DE CITAS\n*/\n\n\n// =========================================\n// 1. ARRAY DE CITAS\n// =========================================\n\nlet citas = [\n  { cliente: \"Marta Ruiz\", servicio: \"Corte\", precio: 25 },\n  { cliente: \"Juan Pérez\", servicio: \"Peinado\", precio: 30 }\n];\n\n\n// =========================================\n// 2. SELECCIONAR ELEMENTOS HTML\n// =========================================\n\nconst listaCitas = document.querySelector(\"#listaCitas\");\nconst totalCitas = document.querySelector(\"#totalCitas\");\nconst importeTotal = document.querySelector(\"#importeTotal\");\n\nconst formulario = document.querySelector(\"#formularioCita\");\nconst nombreCliente = document.querySelector(\"#nombreCliente\");\nconst servicio = document.querySelector(\"#servicio\");\nconst precio = document.querySelector(\"#precio\");\nconst mensaje = document.querySelector(\"#mensaje\");\n\n\n// =========================================\n// RETO 1 · MOSTRAR CITAS\n// RETO 3 · CALCULAR EL TOTAL\n// =========================================\n\nfunction mostrarCitas() {\n\n  listaCitas.innerHTML = \"\";\n\n  let total = 0;\n\n  for (const cita of citas) {\n\n    listaCitas.innerHTML += `\n      <div class=\"cita\">\n        <h3>${cita.cliente}</h3>\n        <p>${cita.servicio}</p>\n        <p class=\"precio\">${cita.precio} €</p>\n      </div>\n    `;\n\n    total += cita.precio;\n  }\n\n  totalCitas.textContent = citas.length;\n  importeTotal.textContent = total + \" €\";\n}\n\n\n// =========================================\n// RETO 2 · AÑADIR CITAS\n// =========================================\n\nfunction agregarCita() {\n\n  // Evitar que el formulario recargue la página\n \n  // Crear el objeto con los datos introducidos\n  const nuevaCita = {\n    cliente: nombreCliente.value.trim(),\n    servicio: servicio.value,\n    precio: Number(precio.value)\n  };\n\n  // Añadir la cita al array\n  citas.push(nuevaCita);\n\n  // Actualizar el listado y el importe\n  mostrarCitas();\n\n  // Limpiar el formulario\n  formulario.reset();\n\n  // Mostrar mensaje\n  mensaje.textContent = \"Cita añadida correctamente.\";\n}\n\n\n// =========================================\n// RETO 4 · BOTONES INFORMATIVOS\n// =========================================\n\nfunction mostrarConsejo(tipo) {\n\n  const mensajeReto4 = document.querySelector(\"#mensajeReto4\");\n\n  if (tipo === \"servicio\") {\n    mensajeReto4.textContent =\n      \"El servicio de la semana es Corte y peinado.\";\n\n  } else if (tipo === \"consejo\") {\n    mensajeReto4.textContent =\n      \"Recuerda terminar con un buen chorro de agua fría.\";\n  }\n}\n\n\n\n\n\n// =========================================\n// INICIO DE LA APLICACIÓN\n// =========================================\n\nmostrarCitas();\n\r\n","materiales/javascript/citas/index.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title></title>\n\n <link rel=\"stylesheet\" href=\"styles.css\">\n <script src=\"app.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- CABECERA -->\n  <header class=\"cabecera\">\n    <div class=\"contenedor contenido-cabecera\">\n\n      <div class=\"marca\">\n        <span>✂ Mi peluquería</span>\n        <span class=\"icono-marca\">💇‍♀️</span>\n      </div>\n\n      <img\n        class=\"imagen-peluqueria\"\n        src=\"images/imagenPeluqueria.png\"\n        alt=\"Ilustración de una peluquería\"\n      >\n\n    </div>\n  </header>\n\n\n  <main class=\"contenedor\">\n\n    <!-- INTRODUCCIÓN -->\n    <div class=\"introduccion\">\n      <h1>Gestor de citas</h1>\n      <p>\n        Registra los servicios de tus clientes\n        y administra las citas de tu peluquería.\n      </p>\n    </div>\n\n    <h2>Los consejos de tu peluquero</h2>\n    <button\n      id=\"servicioSemana\"\n      class=\"boton-consejo\"\n      onclick=\"mostrarConsejo('servicio')\"\n    >\n      Servicio de la semana →\n    </button>\n    <button\n      id=\"consejoPeluqueria\"\n      class=\"boton-consejo\"\n      onclick=\"mostrarConsejo('consejo')\"\n    >\n      Consejo de peluquería →\n    </button>\n    <p id=\"mensajeReto4\" class=\"mensaje\"></p>\n\n\n    <div class=\"distribucion\">\n\n      <!-- ========================= -->\n      <!-- FORMULARIO DE NUEVA CITA -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>1. Nueva cita</h2>\n        <p>Introduce los datos del cliente.</p>\n\n        <form id=\"formularioCita\">\n\n          <!-- NOMBRE -->\n          <div class=\"campo\">\n            <label for=\"nombreCliente\">\n              Nombre del cliente\n            </label>\n\n            <input\n              id=\"nombreCliente\"\n              type=\"text\"\n              placeholder=\"Ej.: Marta Ruiz\"\n              required\n            >\n          </div>\n\n          <!-- SERVICIO -->\n          <div class=\"campo\">\n            <label for=\"servicio\">\n              Servicio\n            </label>\n\n            <select id=\"servicio\" required>\n              <option value=\"\">\n                Selecciona un servicio\n              </option>\n              <option value=\"Corte\">Corte</option>\n              <option value=\"Peinado\">Peinado</option>\n              <option value=\"Tinte\">Tinte</option>\n              <option value=\"Barba\">Barba</option>\n              <option value=\"Corte y peinado\">\n                Corte y peinado\n              </option>\n            </select>\n          </div>\n\n          <!-- PRECIO -->\n          <div class=\"campo\">\n            <label for=\"precio\">\n              Precio (€)\n            </label>\n\n            <input\n              id=\"precio\"\n              type=\"number\"\n              step=\"0.01\"\n              placeholder=\"Ej.: 25\"\n              required\n              min=\"0\"\n            >\n          </div>\n\n          <!-- BOTÓN DE ENVÍO -->\n          <button\n            type=\"submit\"\n            class=\"boton-principal\"\n            onclick=\"agregarCita()\"\n          >\n            Añadir cita →\n          </button>\n\n          <p id=\"mensaje\" class=\"mensaje\"></p>\n\n        </form>\n\n      </section>\n\n\n      <!-- ========================= -->\n      <!-- LISTADO DE CITAS -->\n      <!-- ========================= -->\n\n      <section class=\"panel\">\n\n        <h2>2. Citas registradas</h2>\n        <p>Listado de servicios realizados.</p>\n\n        <p class=\"contador\">\n          Total de citas:\n          <span id=\"totalCitas\">0</span>\n        </p>\n\n        <!-- JavaScript creará aquí las tarjetas -->\n        <div\n          id=\"listaCitas\"\n          class=\"lista-citas\"\n        ></div>\n\n\n        <!-- IMPORTE TOTAL -->\n        <div class=\"resumen-total\">\n\n          <h3>Importe total de las citas</h3>\n\n          <p id=\"importeTotal\">0 €</p>\n\n        </div>\n\n      </section>\n\n    </div>\n\n\n    <!-- ========================= -->\n    <!-- ESPACIO PARA EL RETO 4 -->\n    <!-- ========================= -->\n\n    <!--\n      Aquí crearás una nueva sección\n      con dos botones:\n\n      - Servicio de la semana\n      - Consejo de peluquería\n\n      Añade también un párrafo donde\n      mostrarás los mensajes.\n    -->\n\n\n    <!-- IMAGEN DE DESPEDIDA -->\n    <img\n      class=\"imagen-gracias\"\n      src=\"images/gracias.png\"\n      alt=\"Mensaje de agradecimiento por el curso de desarrollo web\"\n    >\n\n  </main>\n\n\n  <!-- PIE DE PÁGINA -->\n  <footer class=\"pie-pagina\">\n    Práctica final · HTML + CSS + JavaScript\n  </footer>\n\n</body>\n</html>\n","materiales/javascript/citas/styles.css":"\n/* =====================================\n   ESTILOS GENERALES\n===================================== */\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background-color: #f6f4f2;\n  color: #333;\n}\n\n.contenedor {\n  max-width: 1100px;\n  margin: auto;\n  padding: 20px;\n}\n\nh1, h2, h3 {\n  color: #914f57;\n}\n\n\n/* =====================================\n   CABECERA\n===================================== */\n\n.cabecera {\n  background-color: white;\n}\n\n.contenido-cabecera {\n  display: flex;\n  align-items: center;\n  gap: 30px;\n}\n\n.marca {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  font-size: 28px;\n  font-weight: bold;\n  color: #c00d8a;\n  text-align: center;\n}\n\n.icono-marca {\n  font-size: 60px;\n}\n\n.imagen-peluqueria {\n  width: 65%;\n  height: 220px;\n  object-fit: cover;\n  border-radius: 10px;\n}\n\n\n/* =====================================\n   INTRODUCCIÓN\n===================================== */\n\n.introduccion {\n  margin: 20px 0 30px;\n}\n\n\n/* =====================================\n   DISTRIBUCIÓN PRINCIPAL\n===================================== */\n\n.distribucion {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n}\n\n.panel {\n  background-color: white;\n  padding: 25px;\n  border-radius: 10px;\n}\n\n\n/* =====================================\n   CAMPOS DEL FORMULARIO\n===================================== */\n\n.campo {\n  margin-bottom: 20px;\n}\n\nlabel {\n  display: block;\n  margin-bottom: 5px;\n  font-weight: bold;\n}\n\ninput,\nselect {\n  width: 100%;\n  padding: 10px;\n  border: 1px solid #ccc;\n  border-radius: 5px;\n}\n\n\n/* =====================================\n   BOTÓN\n===================================== */\n\n.boton-principal {\n  width: 100%;\n  padding: 12px;\n  background-color: #c00d8a;\n  color: white;\n  border: none;\n  border-radius: 5px;\n  cursor: pointer;\n}\n\n.boton-principal:hover {\n  background-color: #914f57;\n}\n\n.mensaje {\n  color: #914f57;\n  font-weight: bold;\n}\n\n.boton-consejo {\n  padding: 12px;\n  background-color: #c00d8a;\n  color: white;\n  border: none;\n  border-radius: 5px;\n  cursor: pointer;\n  margin-right: 10px;\n}\n\n.boton-consejo:hover {\n  background-color: #914f57;\n}\n\n/* =====================================\n   CITAS REGISTRADAS\n===================================== */\n\n.lista-citas {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.cita {\n  background-color: #f6f4f2;\n  padding: 15px;\n  border-radius: 8px;\n}\n\n.cita h3 {\n  margin: 0 0 5px;\n}\n\n.cita p {\n  margin: 5px 0;\n}\n\n.precio {\n  color: #c00d8a;\n  font-weight: bold;\n}\n\n.contador {\n  font-weight: bold;\n}\n\n\n/* =====================================\n   IMPORTE TOTAL\n===================================== */\n\n.resumen-total {\n  background-color: #f4e4e5;\n  padding: 15px;\n  margin-top: 20px;\n  border-radius: 8px;\n  text-align: center;\n}\n\n#importeTotal {\n  font-size: 25px;\n  font-weight: bold;\n  color: #c00d8a;\n}\n\n\n/* =====================================\n   IMAGEN FINAL Y PIE\n===================================== */\n\n.imagen-gracias {\n  display: block;\n  width: 100%;\n  margin: 30px auto;\n  border-radius: 10px;\n}\n\n.pie-pagina {\n  text-align: center;\n  padding: 20px;\n  background-color: white;\n  color: #666;\n}\n\n\n/* =====================================\n   ADAPTACIÓN A MÓVILES\n===================================== */\n\n@media (max-width: 750px) {\n\n  .distribucion {\n    grid-template-columns: 1fr;\n  }\n\n  .contenido-cabecera {\n    flex-direction: column;\n  }\n\n  .imagen-peluqueria {\n    width: 100%;\n  }\n\n}\n","materiales/javascript/dado/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction lanzarDado() {\n    let resultado = Math.floor(Math.random() * 6) + 1;\n    if (resultado === 6) {\n        document.getElementById(\"resultado\").textContent =\n            `¡Has sacado un 6! Has ganado 🎖️🎖️🎖️`;\n         \n\n    } else {\n        document.getElementById(\"resultado\").textContent =\n            `Has sacado un ${resultado}. ¡Inténtalo otra vez!`;\n    }\n\n \nreturn resultado;\n\n  \n    \n}\n\nfunction actualizarHistorial(resultado) {\n    let historial = document.getElementById(\"historial\");\n    historial.textContent += ` ${resultado}`;\n}\n\n\n\n\n\n\n\n\n\n\n   \r\n","materiales/javascript/dado/dado.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Lanzar el dado</title>\n    <script src=\"app.js\"></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n</head>\n<body>\n    <h1>Lanzar el dado</h1>\n    <img id=\"dado\" src=\"dado.png\" alt=\"Dado\" width=\"100\" height=\"100\">\n    <p>Tira el dado para ver qué número sale.</p>\n    <p>Ganarás si consigues un 6</p>\n    <p id=\"resultado\">Aquí aparecerá el resultado del lanzamiento.</p>\n    <p id=\"historial\">Historial de resultados: </p>   \n\n    <button onclick=\"lanzarDado()\">Lanzar dado</button>\n    <button onclick=\"actualizarHistorial(lanzarDado())\">Actualizar historial</button>\n    </body>\n    \n</html>","materiales/javascript/dado/styles.css":"body{\n    font-family: Arial, sans-serif;\n    text-align: center;\n    margin: auto;\n    background-color: #f0f0f0;\n    border: 4px solid #ccc;\n    width:70%;\n}\n\nh1{\n    color: #333;\n    font-size: 2em;\n}\n\nbutton{\n     \n     background-color: #16c207;\n    margin: 10px 0;\n     padding: 10px 20px;\n     font-size: 1em;\n     cursor: pointer;\n     border-radius: 5px;\n}\n\np{\n    font-size: 1.2em;\n    color: #666;\n}\n\nimg{\n    margin-top: 20px;\n    width: 100px;\n    height: 100px;\n}\n\n#resultado{\n    font-size: 1.5em;\n    font-weight: bold;\n    margin-top: 20px;\n}","materiales/javascript/dom/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction mostrarCurso(curso) {\n  const ficha = document.getElementById(\"ficha-curso\");\n\n  if (curso === \"html\") {\n    ficha.innerHTML = \"<h3>HTML esencial</h3><p>Aprende a estructurar páginas web.</p>\";\n  } else {\n    ficha.innerHTML = \"<h3>JavaScript esencial</h3><p>Haz que tus páginas respondan.</p>\";\n  }\n}\n\nfunction alternarHorarios() {\n  const horarios = document.getElementById(\"horarios\");\n  horarios.classList.toggle(\"horarios--ocultos\");\n}\n\nfunction anadirTarea() {\n  const input = document.getElementById(\"nueva-tarea\");\n  const lista = document.getElementById(\"lista-tareas\");\n  const texto = input.value.trim();\n\n  if (texto !== \"\") {\n    const tarea = document.createElement(\"li\");\n    tarea.textContent = texto;\n    lista.append(tarea);\n    input.value = \"\";\n  }\n}\n\nfunction eliminarUltimaTarea() {\n  const lista = document.getElementById(\"lista-tareas\");\n  const ultimaTarea = lista.lastElementChild;\n\n  if (ultimaTarea) {\n    ultimaTarea.remove();\n  }\n}\r\n","materiales/javascript/dom/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Trabajando el DOM</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <button type=\"button\" onclick=\"mostrarCurso('html')\">Curso HTML</button>\n<button type=\"button\" onclick=\"mostrarCurso('javascript')\">Curso JavaScript</button>\n<section id=\"ficha-curso\"></section>\n\n<button type=\"button\" onclick=\"alternarHorarios()\">Ver horarios</button>\n<section id=\"horarios\" class=\"horarios horarios--ocultos\">\n  <h3>Horarios</h3>\n  <p>Lunes a viernes: 09:00–21:00</p>\n</section>\n\n<label for=\"nueva-tarea\">Nueva tarea</label>\n<input id=\"nueva-tarea\" type=\"text\">\n<button type=\"button\" onclick=\"anadirTarea()\">Añadir tarea</button>\n<button type=\"button\" onclick=\"eliminarUltimaTarea()\">Eliminar última</button>\n<ul id=\"lista-tareas\"></ul>\n\n</body>\n</html>","materiales/javascript/dom/styles.css":"button {\n    margin: 5px;\n    padding: 10px 20px;\n    font-size: 16px;\n}\n\n#ficha-curso {\n    margin-top: 20px;\n    padding: 10px;\n    border: 1px solid #ccc;\n}\n\nbody{\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n}\n.horarios { padding: 1rem; background: #f0f0e9; }\n.horarios--ocultos { display: none; }\n\n\n","materiales/javascript/funciones/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction comprobarEdad(edad) {\n\n    edad = Number(document.getElementById(\"edad\").value);\n\n    if (edad >= 18) {\n         document.getElementById(\"resultado\").textContent = \"Bienvenido puedes entrar🎉🎉🎉🎉🎉 \";\n    } else {\n         document.getElementById(\"resultado\").textContent = \"No puedes entrar❌❌❌❌❌❌ \";\n    }\n    \n}\r\n","materiales/javascript/funciones/funciones.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Control de acceso</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n\n    <h1>Control de acceso a la discoteca</h1>\n\n    <img src=\"discoteca.png\" alt=\"Discoteca\">\n\n    <p>Introduce tu edad para comprobar si puedes entrar.</p>\n\n    <label for=\"edad\">¿Cuántos años tienes?</label>\n    <input type=\"number\" id=\"edad\" min=\"0\">\n\n    <button onclick=\"comprobarEdad()\">\n        Comprobar acceso\n    </button>\n\n    <p id=\"resultado\"></p>\n\n</body>\n</html>\n","materiales/javascript/funciones/styles.css":"body{\n    width:80%;\n    margin: 0 auto;\n    border: 4px solid #131b89;\n    padding: 20px;\n}\nh1{\n    text-align: center;\n    color: #131b89;\n    font-size: 24px;\n}\nbutton{\n    padding: 10px 20px;\n    background-color: #131b89;\n    color: white;\n    border-radius: 5px;\n    cursor: pointer;\n}\n\ninput{\n    border: 2px solid #131b89;\n    border-radius: 5px;\n    padding: 5px;\n}\n\nimg{\n    width:300px;\n    height: auto;\n    border-radius: 10px;\n   \n}","materiales/javascript/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Curso de JavaScript</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <header>\n        <h1>Aprendiendo Javascript</h1>\n        <p>Portada de actividades y ejercicios.</p>\n    </header>\n\n    <main class=\"ejercicios\">\n        <a class=\"ejercicio\" href=\"ejercicio1/ejercicio1.html\">\n            <h2>Actividad 1: Variables</h2>\n            <img src=\"images/variables.png\" alt=\"Vista previa de la Actividad 1\">\n            <p>Declara variables con <code>let</code> y constantes con <code>const</code>.</p>\n        </a>\n        \n    </main>\n</body>\n</html>\n","materiales/javascript/notas/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/*\n   PRÁCTICA: EVALUADOR DE CALIFICACIONES\n\n   Completa los apartados indicados.\n   Utilizaremos IF, ELSE IF, ELSE y SWITCH.\n\n   IMPORTANTE:\n   La función evaluarNota() ya está preparada.\n   No necesitas modificarla ni entender todavía\n   cómo se crean las funciones.\n\n   Escribe tu código dentro de los apartados\n   señalados.\n*/\n\nfunction evaluarNota() {\n\n    // ========================================\n    // 1. OBTENER LOS DATOS DEL HTML\n    // ========================================\n\n    const nombre = document.getElementById(\"nombre\").value;\n\n    const notaTexto = document.getElementById(\"nota\").value;\n    const nota = Number(notaTexto);\n\n\n    // ========================================\n    // 2. DECLARAR VARIABLES\n    // ========================================\n\n    let calificacion = \"\";\n    let mensaje = \"\";\n\n\n    // ========================================\n    // 3. COMPROBAR QUE LA NOTA ES VÁLIDA\n    // Esta parte ya está resuelta.\n    // ========================================\n\n    if (notaTexto.trim() === \"\" || nota < 0 || nota > 10) {\n\n        document.getElementById(\"resultado\").textContent =\n            \"Introduce una nota válida entre 0 y 10.\";\n\n        document.getElementById(\"mensaje\").textContent = \"\";\n\n        return;\n    } /*fin de la funcion*/\n\n\n    // ========================================\n    // 4. TU TURNO: IF...ELSE IF...ELSE\n    // ========================================\n\n    /*\n       Determina la calificación del alumno:\n\n       Menos de 5     → Suspenso\n       Desde 5 a < 6  → Suficiente\n       Desde 6 a < 7  → Bien\n       Desde 7 a < 9  → Notable\n       Desde 9 a 10   → Sobresaliente\n\n       Guarda el resultado en la variable\n       calificacion que ya esta declarada. No la declares sólo evalua su nota. La nota te vendrá del HTML.\n\n       Utiliza if, else if y else.\n    */\n\n  \n\n\n\n\n\n    // ========================================\n    // 5. TU TURNO: SWITCH\n    // ========================================\n\n    /*\n       Según el valor de calificacion,\n       guarda en la variable mensaje:\n\n       Suspenso:\n       \"Necesitas seguir practicando.\"\n\n       Suficiente:\n       \"Has conseguido aprobar.\"\n\n       Bien:\n       \"Buen trabajo.\"\n\n       Notable:\n       \"Muy buen resultado.\"\n\n       Sobresaliente:\n       \"Excelente trabajo.\"\n\n       Utiliza switch, case, break y default.\n    */\n\n    // ESCRIBE AQUÍ TU CÓDIGO\n    \n\n\n\n\n\n    // ========================================\n    // 6. MOSTRAR RESULTADOS EN HTML\n    // Esta parte ya está resuelta. Esta vez quiero que te concentres en la lógica de calificación y mensaje.\n    // ========================================\n\n    document.getElementById(\"resultado\").textContent =\n        nombre + \", has obtenido un \" + calificacion +\n        \" con una nota de \" + nota + \".\";\n\n    document.getElementById(\"mensaje\").textContent = mensaje;\n\n}\n\r\n","materiales/javascript/notas/notas.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Calculadora de notas</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Evaluador de calificaciones</h1>\n\n<label for=\"nombre\">Nombre del alumno:</label>\n<input type=\"text\" id=\"nombre\">\n\n<label for=\"nota\">Introduce la nota:</label>\n<input type=\"number\" id=\"nota\" min=\"0\" max=\"10\" step=\"0.1\">\n\n\n<button type=\"button\" onclick=\"evaluarNota()\">\n    Evaluar nota\n</button>\n\n<h2>Resultado de la evaluación</h2>\n\n<p id=\"resultado\"></p>\n\n<h3>Mensaje para el alumno</h3>\n<p id=\"mensaje\"></p>\n\n\n\n\n</body>\n</html>","materiales/javascript/notas/styles.css":"\n/* Estilos generales */\nbody {\n    font-family: Arial, sans-serif;\n    background-color: #f4f6f9;\n    color: #333;\n    max-width: 500px;\n    margin: 50px auto;\n    padding: 25px;\n    border: 1px solid #ddd;\n    border-radius: 10px;\n}\n\n/* Título */\nh1 {\n    color: #2456a6;\n    text-align: center;\n}\n\n/* Etiquetas */\nlabel {\n    display: block;\n    margin-top: 20px;\n    margin-bottom: 8px;\n    font-weight: bold;\n}\n\n/* Campos de entrada */\ninput {\n    display: block;\n    width: 100%;\n    padding: 10px;\n    border: 1px solid #ccc;\n    border-radius: 5px;\n    box-sizing: border-box;\n}\n\n/* Botón */\nbutton {\n    background-color: #2456a6;\n    color: white;\n    border: none;\n    padding: 12px 20px;\n    margin-top: 25px;\n    border-radius: 5px;\n    cursor: pointer;\n    width: 100%;\n}\n\n/* Botón al pasar el ratón */\nbutton:hover {\n    background-color: #173c78;\n}\n\n/* Resultados */\nh2 {\n    margin-top: 30px;\n    color: #2456a6;\n}\n\n#resultado,\n#mensaje {\n    font-weight: bold;\n    color: #2456a6;\n}\n","materiales/javascript/styles.css":":root {\n    font-family: Arial, sans-serif;\n    color: #1f1f1f;\n    background: #f7df1e;\n}\n\n* {\n    box-sizing: border-box;\n}\n\nbody {\n    margin: 0;\n    min-height: 100vh;\n    padding: 48px;\n    background: linear-gradient(135deg, #f7df1e, #fff7c2);\n}\n\nheader,\n.ejercicios {\n    width: min(1200px, 100%);\n    margin: 0 auto;\n}\n\nheader {\n    margin-bottom: 32px;\n}\n\nh1 {\n    margin-bottom: 8px;\n}\n\nheader p {\n    margin-top: 0;\n}\n\n.ejercicios {\n    display: grid;\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    gap: 20px;\n}\n\n.ejercicio {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    align-items: center;\n    justify-content: space-between;\n    padding: 24px;\n    color: #222;\n    text-decoration: none;\n    background: #fff;\n    border-radius: 12px;\n    box-shadow: 0 8px 20px rgba(0, 0, 0, .12);\n    transition: transform .2s, background-color .2s;\n}\n\n.ejercicio h2,\n.ejercicio p {\n    margin: 0;\n    text-align: center;\n}\n\n.ejercicio img {\n    width: 100%;\n    height: 150px;\n    object-fit: cover;\n    border-radius: 8px;\n}\n\n.ejercicio:hover,\n.ejercicio:focus-visible {\n    background: #fff4aa;\n    transform: translateY(-4px);\n}\n\n\n\n@media (max-width: 900px) {\n    .ejercicios {\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n}\n\n@media (max-width: 560px) {\n    body {\n        padding: 24px;\n    }\n\n    .ejercicios {\n        grid-template-columns: 1fr;\n    }\n}\n","materiales/javascript/tareas/app.js":"","materiales/javascript/tareas/index.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title>Mi agenda de tareas</title>\n\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"app.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- CABECERA -->\n  <header class=\"cabecera\">\n  <div class=\"contenedor\">\n    <h1>🚀 Mi agenda de tareas</h1>\n    <p>¡La práctica te hará experto!</p>\n\n    <img\n      src=\"images/tareas.png\"\n      alt=\"Astronauta completando misiones de programación en el espacio\"\n      class=\"imagen-cabecera\"\n    >\n  </div>\n</header>\n\n\n  <main class=\"contenedor\">\n\n    <div class=\"distribucion\">\n\n      <!-- FORMULARIO -->\n      <section class=\"panel\">\n\n        <h2>1. Nueva tarea</h2>\n        <p>Introduce los datos de tu actividad.</p>\n\n        <form id=\"formularioTarea\">\n\n          <!-- NOMBRE -->\n          <div class=\"campo\">\n            <label for=\"nombreTarea\">\n              Nombre de la tarea\n            </label>\n\n            <input\n              id=\"nombreTarea\"\n              type=\"text\"\n              placeholder=\"Ej.: Repasar JavaScript\"\n            >\n          </div>\n\n          <!-- CATEGORÍA -->\n          <div class=\"campo\">\n            <label for=\"categoria\">\n              Categoría\n            </label>\n\n            <select id=\"categoria\">\n              <option value=\"\">\n                Selecciona una categoría\n              </option>\n              <option value=\"Estudio\">Estudio</option>\n              <option value=\"Trabajo\">Trabajo</option>\n              <option value=\"Personal\">Personal</option>\n              <option value=\"Ocio\">Ocio</option>\n            </select>\n          </div>\n\n          <!-- DURACIÓN -->\n          <div class=\"campo\">\n            <label for=\"minutos\">\n              Duración (minutos)\n            </label>\n\n            <input\n              id=\"minutos\"\n              type=\"number\"\n              placeholder=\"Ej.: 30\"\n            >\n          </div>\n\n          <!-- BOTÓN -->\n          <button\n            type=\"button\"\n            class=\"boton-principal\"\n            onclick=\"agregarTarea()\"\n          >\n            Añadir tarea\n          </button>\n\n          <p id=\"mensaje\" class=\"mensaje\"></p>\n\n        </form>\n\n      </section>\n\n\n      <!-- LISTADO DE TAREAS -->\n      <section class=\"panel\">\n\n        <h2>2. Tareas registradas</h2>\n        <p>Estas son tus actividades pendientes.</p>\n\n        <p class=\"contador\">\n          Total de tareas:\n          <span id=\"totalTareas\">0</span>\n        </p>\n\n        <!-- JavaScript añadirá las tareas aquí -->\n        <div\n          id=\"listaTareas\"\n          class=\"lista-tareas\"\n        ></div>\n\n        <!-- TIEMPO TOTAL -->\n        <div class=\"resumen-total\">\n\n          <h3>Tiempo total de las tareas</h3>\n\n          <p id=\"tiempoTotal\">0 minutos</p>\n\n        </div>\n\n      </section>\n\n    </div>\n\n\n    <!-- ACTIVIDAD DE HTML, CSS Y EVENTOS -->\n    <!-- Los alumnos añadirán aquí dos botones\n         y un párrafo para mostrar mensajes. -->\n\n\n  </main>\n\n\n  <!-- PIE DE PÁGINA -->\n  <footer class=\"pie-pagina\">\n    Práctica de repaso · HTML + CSS + JavaScript\n  </footer>\n\n</body>\n</html>\n","materiales/javascript/tareas/solucion.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title>Mi agenda de tareas</title>\n\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"solucion.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- CABECERA -->\n  <header class=\"cabecera\">\n  <div class=\"contenedor\">\n    <h1>🚀 Mi agenda de tareas</h1>\n    <p>¡La práctica te hará experto!</p>\n\n    <img\n      src=\"images/tareas.png\"\n      alt=\"Astronauta completando misiones de programación en el espacio\"\n      class=\"imagen-cabecera\"\n    >\n  </div>\n</header>\n\n\n  <main class=\"contenedor\">\n\n    <div class=\"distribucion\">\n\n      <!-- FORMULARIO -->\n      <section class=\"panel\">\n\n        <h2>1. Nueva tarea</h2>\n        <p>Introduce los datos de tu actividad.</p>\n\n        <form id=\"formularioTarea\">\n\n          <!-- NOMBRE -->\n          <div class=\"campo\">\n            <label for=\"nombreTarea\">\n              Nombre de la tarea\n            </label>\n\n            <input\n              id=\"nombreTarea\"\n              type=\"text\"\n              placeholder=\"Ej.: Repasar JavaScript\"\n            >\n          </div>\n\n          <!-- CATEGORÍA -->\n          <div class=\"campo\">\n            <label for=\"categoria\">\n              Categoría\n            </label>\n\n            <select id=\"categoria\">\n              <option value=\"\">\n                Selecciona una categoría\n              </option>\n              <option value=\"Estudio\">Estudio</option>\n              <option value=\"Trabajo\">Trabajo</option>\n              <option value=\"Personal\">Personal</option>\n              <option value=\"Ocio\">Ocio</option>\n            </select>\n          </div>\n\n          <!-- DURACIÓN -->\n          <div class=\"campo\">\n            <label for=\"minutos\">\n              Duración (minutos)\n            </label>\n\n            <input\n              id=\"minutos\"\n              type=\"number\"\n              placeholder=\"Ej.: 30\"\n            >\n          </div>\n\n          <!-- BOTÓN -->\n          <button\n            type=\"button\"\n            class=\"boton-principal\"\n            onclick=\"agregarTarea()\"\n          >\n            Añadir tarea\n          </button>\n\n          <p id=\"mensaje\" class=\"mensaje\"></p>\n\n        </form>\n\n      </section>\n\n\n      <!-- LISTADO DE TAREAS -->\n      <section class=\"panel\">\n\n        <h2>2. Tareas registradas</h2>\n        <p>Estas son tus actividades pendientes.</p>\n\n        <p class=\"contador\">\n          Total de tareas:\n          <span id=\"totalTareas\">0</span>\n        </p>\n\n        <!-- JavaScript añadirá las tareas aquí -->\n        <div\n          id=\"listaTareas\"\n          class=\"lista-tareas\"\n        ></div>\n\n        <!-- TIEMPO TOTAL -->\n        <div class=\"resumen-total\">\n\n          <h3>Tiempo total de las tareas</h3>\n\n          <p id=\"tiempoTotal\">0 minutos</p>\n\n        </div>\n\n      </section>\n\n    </div>\n\n\n    <!-- ACTIVIDAD DE HTML, CSS Y EVENTOS -->\n    <!-- Los alumnos añadirán aquí dos botones\n         y un párrafo para mostrar mensajes. -->\n\n\n  </main>\n\n\n  <!-- PIE DE PÁGINA -->\n  <footer class=\"pie-pagina\">\n    Práctica de repaso · HTML + CSS + JavaScript\n  </footer>\n\n</body>\n</html>\n\r\n","materiales/javascript/tareas/solucion.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Al iniciar, se recuperan los datos guardados y se actualiza el array. Al añadir un dato: push(), guardar en localStorage y volver a mostrar el listado.\r\n * JSON.stringify convierte arrays u objetos en texto para guardarlos; JSON.parse recupera de nuevo su estructura.\r\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/*\n  MI AGENDA DE TAREAS\n  PRÁCTICA DE REPASO\n*/\n\n\n// =========================================\n// RETO 1 · ARRAY DE TAREAS\n// =========================================\n\nlet tareas = [\n  { nombre: \"Estudiar JavaScript\", categoria: \"Estudio\", minutos: 120 },\n  { nombre: \"Hacer ejercicio\", categoria: \"Personal\", minutos: 60 }\n];\n\n//esta linea es la última que incorporamos y lo hacemos \n//porque tenemos las tareas guardadas en el localstorage \n// y queremos que al recargar la página se muestren las tareas guardadas nuevas \n// y no las que tenemos en el array por defecto\n\n\ntareas = recuperarTareasLocal() || tareas;\n\n// =========================================\n// RETO 1 · MOSTRAR LAS TAREAS\n// =========================================\n\nfunction mostrarTareas() {\n\n  // Seleccionamos el contenedor del HTML\n  const listaTareas = document.getElementById(\"listaTareas\");\n\n  // Limpiamos para no repetir las tarjetas\n  listaTareas.innerHTML = \"\";\n\n  // Recorremos el array\n  for (const tarea of tareas) {\n\n    listaTareas.innerHTML += `\n      <article class=\"tarea\">\n        <h3>${tarea.nombre}</h3>\n        <p>Categoría: ${tarea.categoria}</p>\n        <p class=\"duracion\">Duración: ${tarea.minutos} minutos</p>\n      </article>\n    `;\n\n  }\n\n  // Actualizamos el contador\n  document.getElementById(\"totalTareas\").textContent = tareas.length;\n\n  // llamo a calcularTiempo para que al mostrar las tareas me calcule \n  // el tiempo total de todas las tareas y me lo muestre en el HTML\ndocument.getElementById(\"tiempoTotal\").textContent = calcularTiempoTotal() + \" minutos\";\n  \n\n}\nmostrarTareas();\nrecuperarTareasLocal();\n\n\n// =========================================\n// RETO 2 · AÑADIR TAREAS\n// =========================================\n\nfunction agregarTarea() {\n\n  \n\n  // Obtenemos los valores del formulario\n  const nombre = document.getElementById(\"nombreTarea\").value;\n  const categoria = document.getElementById(\"categoria\").value;\n  const minutos = Number(document.getElementById(\"minutos\").value);\n\n  // Creamos el objeto\n  const tarea = {\n    nombre: nombre,\n    categoria: categoria,\n    minutos: minutos\n  };\n\n  // Añadimos la tarea al array\n  tareas.push(tarea);\n  guardarTareasLocal();\n\n  // Limpiamos el formulario\n  document.getElementById(\"formularioTarea\").reset();\n\n  // Actualizamos las tareas las mostramos en el HTML \n  mostrarTareas();\n \n\n}\n\n// =========================================\n// RETO 3 · CONTADOR DE TIEMPO DE TAREAS\n// =========================================\n\n\n function calcularTiempoTotal() {\n    //declaramos una variable para guardar el tiempo total\n      let tiempoTareas = 0;\n     for (const tarea of tareas) {\n    //sumamos el tiempo de cada tarea al tiempo total\n      tiempoTareas += tarea.minutos;\n    }\n    //devolvemos el tiempo acumulado de todas las tareas para luego poderlo mostrar en el HTML\n    return tiempoTareas;\n    \n  }\n\n  //====================================\n  //RETO 4 . GUARDAR TAREAS EN LOCALSTORAGE\n  //====================================\n  //funcion para guardar las tareas en el localstorage\n  function guardarTareasLocal() {\n    localStorage.setItem(\"tareas\", JSON.stringify(tareas));\n  }\n\n  //====================================\n  //RETO 5 . RECUPERAR TAREAS DEL LOCALSTORAGE\n  //====================================\n  \n  //funcion para cargar las tareas del localstorage \n  function recuperarTareasLocal() {\n\n  // Recuperamos el texto guardado\n  const tareasGuardadas = localStorage.getItem(\"tareas\");\n\n  // Si existen datos guardados, los convertimos en un array\n  if (tareasGuardadas) {\n    tareas = JSON.parse(tareasGuardadas);\n  }\n\n}\r\n","materiales/javascript/tareas/styles.css":"\n/* =====================================\n   ESTILOS GENERALES\n===================================== */\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background-color: #10172e;\n  color: #e5e7eb;\n}\n\n.contenedor {\n  max-width: 1000px;\n  margin: auto;\n  padding: 20px;\n}\n\n\n/* =====================================\n   CABECERA ESPACIAL\n===================================== */\n\n.cabecera {\n  background-color: #192750;\n  text-align: center;\n  padding: 20px;\n}\n\n.cabecera h1 {\n  color: #ffffff;\n  font-size: 32px;\n  margin-bottom: 10px;\n}\n\n.cabecera p {\n  color: #b9d8ff;\n}\n\n.imagen-cabecera {\n  display: block;\n  width: 100%;\n  height: 300px;\n  object-fit: cover;\n  border-radius: 10px;\n  margin-top: 20px;\n}\n\n\n/* =====================================\n   DISTRIBUCIÓN PRINCIPAL\n===================================== */\n\n.distribucion {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n  margin-top: 30px;\n}\n\n.panel {\n  background-color: #202d50;\n  padding: 25px;\n  border-radius: 10px;\n}\n\nh2 {\n  color: #7dd3fc;\n}\n\n\n/* =====================================\n   FORMULARIO\n===================================== */\n\n.campo {\n  margin-bottom: 20px;\n}\n\nlabel {\n  display: block;\n  margin-bottom: 5px;\n  font-weight: bold;\n}\n\ninput,\nselect {\n  width: 100%;\n  padding: 10px;\n  border: 1px solid #65749b;\n  border-radius: 5px;\n  background-color: #ffffff;\n  color: #222;\n}\n\n\n/* =====================================\n   BOTÓN PRINCIPAL\n===================================== */\n\n.boton-principal {\n  width: 100%;\n  padding: 12px;\n  background-color: #2563eb;\n  color: white;\n  border: none;\n  border-radius: 5px;\n  cursor: pointer;\n  font-size: 15px;\n}\n\n.boton-principal:hover {\n  background-color: #7c3aed;\n}\n\n.mensaje {\n  color: #67e8f9;\n  font-weight: bold;\n}\n\n\n/* =====================================\n   TARJETAS DE TAREAS\n===================================== */\n\n.lista-tareas {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.tarea {\n  background-color: #303e68;\n  padding: 15px;\n  border-left: 4px solid #38bdf8;\n  border-radius: 8px;\n}\n\n.tarea h3 {\n  color: #ffffff;\n  margin: 0 0 5px;\n}\n\n.tarea p {\n  margin: 5px 0;\n}\n\n.duracion {\n  color: #fbbf24;\n  font-weight: bold;\n}\n\n.contador {\n  font-weight: bold;\n  color: #b9d8ff;\n}\n\n\n/* =====================================\n   TIEMPO TOTAL\n===================================== */\n\n.resumen-total {\n  background-color: #374174;\n  padding: 15px;\n  margin-top: 20px;\n  border-radius: 8px;\n  text-align: center;\n}\n\n#tiempoTotal {\n  font-size: 25px;\n  font-weight: bold;\n  color: #fbbf24;\n}\n\n\n/* =====================================\n   PIE DE PÁGINA\n===================================== */\n\n.pie-pagina {\n  text-align: center;\n  padding: 20px;\n  margin-top: 30px;\n  background-color: #192750;\n  color: #b9d8ff;\n}\n\n\n/* =====================================\n   ADAPTACIÓN A MÓVILES\n===================================== */\n\n@media (max-width: 750px) {\n\n  .distribucion {\n    grid-template-columns: 1fr;\n  }\n\n  .imagen-cabecera {\n    height: auto;\n  }\n\n}\n","materiales/javascript/tienda/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n// ==========================================\n// TECNOAULA · JAVASCRIPT CONTROLA LA PÁGINA\n// ==========================================\n\n\n// ==========================================\n// DATOS DE NUESTRA TIENDA\n// Cada objeto representa un producto.\n// ==========================================\n\nconst productos = [\n  { id: 1, nombre: \"Teclado\", precio: 35, categoria: \"Periféricos\", icono: \"⌨️\" },\n  { id: 2, nombre: \"Ratón\", precio: 20, categoria: \"Periféricos\", icono: \"🖱️\" },\n  { id: 3, nombre: \"Auriculares\", precio: 50, categoria: \"Audio\", icono: \"🎧\" },\n  { id: 4, nombre: \"Monitor\", precio: 150, categoria: \"Pantallas\", icono: \"🖥️\" }\n];\n\n\n// ==========================================\n// RETO 1 · SALUDO SEGÚN LA HORA\n// ==========================================\n\n// Obtenemos la hora actual del navegador.\nconst hora = new Date().getHours();\n\n// Localizamos el título del saludo.\nconst saludo = document.querySelector(\"#saludo\");\n\n// Cambiamos el texto según la hora.\nif (hora < 12) {\n  saludo.textContent = \"Buenos días, bienvenido a TecnoAula\";\n\n} else if (hora < 20) {\n  saludo.textContent = \"Buenas tardes, bienvenido a TecnoAula\";\n\n} else {\n  saludo.textContent = \"Buenas noches, bienvenido a TecnoAula\";\n}\n\n\n// ==========================================\n// RETO 2 · MOSTRAR PROMOCIONES\n// ==========================================\n\n// Los botones envían \"ofertas\" o \"destacados\".\n\nfunction mostrarPromocion(tipo) {\n\n  const promocion = document.querySelector(\"#promocion\");\n\n  if (tipo === \"ofertas\") {\n\n    promocion.innerHTML = `\n      <h3>¡Ofertas especiales!</h3>\n      <p>Teclado por solo 35 €.</p>\n      <p>Ratón por solo 20 €.</p>\n    `;\n\n  } else {\n\n    promocion.innerHTML = `\n      <h3>Nuestros productos destacados</h3>\n      <p>Auriculares por 50 €.</p>\n      <p>Monitor por 150 €.</p>\n    `;\n  }\n}\n\n\n// ==========================================\n// RETO 3 · GENERAR EL CATÁLOGO\n// ==========================================\n\n/*\nPRIMERA VERSIÓN\n\nMostramos los productos sin botones de compra.\n\nEsta versión queda comentada porque después\nla sustituimos por la versión con botones.\n*/\n\n/*\nfunction mostrarProductos() {\n\n  const catalogo = document.querySelector(\"#catalogo\");\n\n  // Vaciamos el contenido anterior.\n  catalogo.innerHTML = \"\";\n\n  // Recorremos el array de productos.\n  for (const producto of productos) {\n\n    catalogo.innerHTML += `\n      <article class=\"tarjeta\">\n\n        <div class=\"icono-producto\">\n          ${producto.icono}\n        </div>\n\n        <h3>${producto.nombre}</h3>\n\n        <p class=\"categoria\">\n          ${producto.categoria}\n        </p>\n\n        <p class=\"precio\">\n          ${producto.precio} €\n        </p>\n\n      </article>\n    `;\n  }\n\n  const contador = document.querySelector(\"#contador-productos\");\n  contador.textContent = productos.length;\n}\n*/\n\n\n// ==========================================\n// RETO 4 · AÑADIR BOTONES AL CATÁLOGO\n// ==========================================\n\n// SEGUNDA VERSIÓN DE mostrarProductos().\n// Añadimos un botón a cada tarjeta.\n// Esta es la versión activa.\n\nfunction mostrarProductos() {\n\n  // Localizamos el catálogo.\n  const catalogo = document.querySelector(\"#catalogo\");\n\n  // Borramos el contenido anterior.\n  catalogo.innerHTML = \"\";\n\n  // Recorremos los productos.\n  for (const producto of productos) {\n\n    // Creamos una tarjeta por cada producto.\n    catalogo.innerHTML += `\n      <article class=\"tarjeta\">\n\n        <div class=\"icono-producto\">\n          ${producto.icono}\n        </div>\n\n        <h3>${producto.nombre}</h3>\n\n        <p class=\"categoria\">\n          ${producto.categoria}\n        </p>\n\n        <p class=\"precio\">\n          ${producto.precio} €\n        </p>\n\n        <button onclick=\"agregarCarrito(${producto.id})\">\n          Añadir al carrito 🛒\n        </button>\n\n      </article>\n    `;\n  }\n\n  // Actualizamos el contador.\n  const contador = document.querySelector(\"#contador-productos\");\n  contador.textContent = productos.length;\n}\n\nmostrarProductos();\n\n\n// ==========================================\n// RETO 5 · AÑADIR PRODUCTOS AL CARRITO\n// ==========================================\n\n// Creamos un array vacío para guardar la compra.\n\nlet carrito = [];\n\nfunction agregarCarrito(id) {\n\n  // Buscamos el producto que corresponde al id.\n  const producto = productos.find(p => p.id === id);\n\n  // Añadimos el producto encontrado.\n  if (producto) {\n    carrito.push(producto);\n  }\n\n  console.log(carrito);\n\n  // Actualizamos el carrito y el total.\n  mostrarCarrito();\n  calcularTotal();\n}\n\n\n// ==========================================\n// RETO 6 · MOSTRAR EL CARRITO\n// ==========================================\n\nfunction mostrarCarrito() {\n\n  // Localizamos la zona del carrito.\n  const lista = document.querySelector(\"#lista-carrito\");\n\n  // Limpiamos para que no se repitan los productos.\n  lista.innerHTML = \"\";\n\n  // Recorremos el carrito utilizando un índice.\n  for (let i = 0; i < carrito.length; i++) {\n\n    const producto = carrito[i];\n\n    lista.innerHTML += `\n      <p>\n        ${producto.nombre} - ${producto.precio} €\n\n        <button onclick=\"eliminarCarrito(${i})\">\n          Eliminar ❌\n        </button>\n      </p>\n    `;\n  }\n}\n\n\n// ==========================================\n// RETO 7 · CALCULAR EL TOTAL\n// ==========================================\n\nfunction calcularTotal() {\n\n  // Empezamos con el total a cero.\n  let total = 0;\n\n  // Sumamos el precio de cada producto.\n  for (const producto of carrito) {\n    total = total + producto.precio;\n  }\n\n  // Mostramos el resultado.\n  const resultado = document.querySelector(\"#total-carrito\");\n\n  resultado.textContent = total + \" €\";\n\n  console.log(total);\n}\n\n\n// ==========================================\n// RETO 8 · ELIMINAR UN PRODUCTO\n// ==========================================\n\nfunction eliminarCarrito(posicion) {\n\n  // Eliminamos un elemento del array.\n  carrito.splice(posicion, 1);\n\n  // Volvemos a mostrar el carrito y el total.\n  mostrarCarrito();\n  calcularTotal();\n}\n\n\n// ==========================================\n// RETO 9 · FINALIZAR COMPRA\n// ==========================================\n\nfunction finalizarCompra() {\n\n  // Localizamos el párrafo del mensaje.\n  const mensaje = document.querySelector(\"#mensaje-compra\");\n\n  // Mostramos la confirmación.\n  mensaje.textContent =\n    \"Tu compra se ha finalizado. Gracias por tu compra.\";\n}\n\n\n// ==========================================\n// MOSTRAR EL CARRITO AL ABRIR LA PÁGINA\n// ==========================================\n\n// Al principio el carrito está vacío.\nmostrarCarrito();\ncalcularTotal();\n\n\n// ==========================================\n// CREAR ELEMENTOS CON createElement\n// ==========================================\n\n// Creamos los elementos HTML.\nconst novedades = document.createElement(\"h3\");\n\nconst productosNuevos = document.createElement(\"p\");\n\n// Asignamos una clase CSS.\nnovedades.className = \"h3\";\n\n// Añadimos contenido a los elementos.\nproductosNuevos.textContent =\n  \"No te pierdas nuestras novedades que te facilitarán la vida.\";\n\nnovedades.textContent = \"Nuestros productos más recientes\";\n\n// Seleccionamos el contenedor HTML.\nconst contenedor = document.querySelector(\".productos\");\n\n// Añadimos los elementos al contenedor.\ncontenedor.append(novedades, productosNuevos);\n\n\n// ==========================================\n// BUSCADOR DE PRODUCTOS\n// ==========================================\n\n/*\nBuscamos un producto por su nombre.\n\nUtilizamos:\n- find()\n- toLowerCase()\n- trim()\n\nSi lo encontramos, mostramos sus datos.\nSi no, mostramos un mensaje.\n*/\n\nfunction buscarProductos() {\n\n  const nombre = document.getElementById(\"buscador\").value;\n\n  // Normalizamos el nombre.\n  const nombreNormalizado = nombre.toLowerCase().trim();\n\n  // Buscamos el producto en el array.\n  const productoEncontrado = productos.find(\n    producto =>\n      producto.nombre.toLowerCase().trim() === nombreNormalizado\n  );\n\n  // Mostramos el resultado.\n  if (productoEncontrado) {\n\n    document.getElementById(\"resultado\").textContent =\n      \"Producto encontrado: \" + productoEncontrado.nombre +\n      \" su precio es \" + productoEncontrado.precio + \" €\";\n\n  } else {\n\n    document.getElementById(\"resultado\").textContent =\n      \"Tu producto no ha sido encontrado.\";\n  }\n}\n\r\n","materiales/javascript/tienda/index.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\n  <title>TecnoAula · JavaScript controla la página</title>\n\n  <!-- Archivo de estilos -->\n  <link rel=\"stylesheet\" href=\"styles.css\">\n\n  <!-- defer permite cargar el HTML antes de ejecutar JavaScript -->\n  <script src=\"app.js\" defer></script>\n</head>\n\n<body>\n\n  <!-- =====================================\n       CABECERA DE LA TIENDA\n  ====================================== -->\n\n  <header class=\"cabecera\">\n\n    <div class=\"contenedor cabecera-interior\">\n\n      <a class=\"marca\" href=\"#inicio\">\n        Tecno<span>Aula</span>\n      </a>\n\n      <span class=\"etiqueta\">Práctica JavaScript</span>\n\n    </div>\n\n  </header>\n\n\n  <main id=\"inicio\" class=\"contenedor\">\n\n    <!-- =====================================\n         RETO 1 · SALUDO SEGÚN LA HORA\n    ====================================== -->\n\n    <section class=\"bienvenida\">\n\n      <p class=\"sobrelinea\">TU TIENDA DE INFORMÁTICA</p>\n\n      <!-- JavaScript cambiará este título según la hora -->\n      <h1 id=\"saludo\">Bienvenido a TecnoAula</h1>\n\n      <p id=\"mensaje-tienda\">\n        Encuentra los mejores accesorios para tu ordenador.\n      </p>\n\n\n      <!-- =====================================\n           RETO 2 · PROMOCIONES INTERACTIVAS\n      ====================================== -->\n\n      <section class=\"promociones\">\n\n        <h2>Descubre nuestras promociones</h2>\n\n        <!--\n          Ambos botones ejecutan la misma función,\n          pero cada uno envía un argumento diferente.\n        -->\n\n        <button\n          type=\"button\"\n          onclick=\"mostrarPromocion('ofertas')\">\n          Ver productos en oferta\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"mostrarPromocion('destacados')\">\n          Ver productos destacados\n        </button>\n\n        <!--\n          JavaScript mostrará aquí el mensaje\n          correspondiente al botón pulsado.\n\n          Utilizaremos innerHTML.\n        -->\n        <div id=\"promocion\"></div>\n\n      </section>\n\n    </section>\n\n    <!--BUSCADOR DE PRODUCTOS-->\n    <label for=\"buscador\">Buscar productos:</label>\n    <input type=\"text\" id=\"buscador\" placeholder=\"Buscar productos...\">\n    <button type=\"button\" onclick=\"buscarProductos()\">Buscar</button>\n    <p id=\"resultado\"></p>\n\n\n    <!-- =====================================\n         CATÁLOGO Y CARRITO\n    ====================================== -->\n\n    <div class=\"distribucion\">\n\n\n      <!-- =====================================\n           RETO 3 · CATÁLOGO DE PRODUCTOS\n      ====================================== -->\n\n      <section class=\"productos\">\n\n        <div class=\"encabezado\">\n\n          <div>\n\n            <p class=\"sobrelinea\">EQUIPA TU ESCRITORIO</p>\n\n            <h2>Nuestro catálogo</h2>\n\n          </div>\n\n          <!-- JavaScript actualizará el número de productos -->\n          <p class=\"contador\">\n            Productos: <strong id=\"contador-productos\">0</strong>\n          </p>\n\n        </div>\n\n\n        <!--\n          RETO 3: GENERAR EL CATÁLOGO\n\n          Tenemos un array de objetos en JavaScript.\n\n          Recorreremos ese array con for...of\n          para mostrar una tarjeta por cada producto.\n\n          Cada tarjeta tendrá:\n          - Un icono\n          - El nombre del producto\n          - Su categoría\n          - Su precio\n\n          Utilizaremos innerHTML y plantillas literales.\n        -->\n\n        <div id=\"catalogo\" class=\"catalogo\">\n\n          <p class=\"vacio\">\n            El catálogo aparecerá cuando completes el reto 3.\n          </p>\n\n        </div>\n\n      </section>\n\n\n      <!-- =====================================\n           PRÓXIMA FASE · CARRITO DE COMPRA\n      ====================================== -->\n\n      <aside class=\"carrito\">\n\n        <div class=\"encabezado-carrito\">\n\n          <h2>Mi carrito</h2>\n\n          <span>🛒</span>\n\n        </div>\n\n        <p class=\"ayuda\">\n          Lo programaremos en la siguiente fase.\n        </p>\n\n        <!--\n          Aquí aparecerán los productos\n          que el usuario añada al carrito.\n        -->\n        <div id=\"lista-carrito\">\n\n          <p class=\"vacio\">\n            Todavía no hay productos añadidos.\n          </p>\n\n        </div>\n\n        <!--\n          JavaScript calculará el total\n          de los productos seleccionados.\n        -->\n        <div class=\"total\">\n\n          <strong>Total</strong>\n\n          <strong id=\"total-carrito\">0 €</strong>\n\n        </div>\n\n       \n<!-- RETO 9 · FINALIZAR COMPRA -->\n\n<button type=\"button\" onclick=\"finalizarCompra()\">\n  Finalizar compra\n</button>\n\n<!-- Aquí mostraremos el resultado de la compra totalizada-->\n<p id=\"mensaje-compra\"></p>\n\n\n      </aside>\n\n    </div>\n\n  </main>\n\n\n  <!-- =====================================\n       PIE DE PÁGINA\n  ====================================== -->\n\n  <footer class=\"pie\">\n    TecnoAula · Aprender JavaScript creando una página real\n  </footer>\n\n</body>\n</html>\n","materiales/javascript/tienda/styles.css":"\n/* ESTILOS GENERALES */\n\nbody {\n  margin: 0;\n  font-family: Arial, sans-serif;\n  background-color: #f1f5f9;\n  color: #243447;\n}\n\n.contenedor {\n  max-width: 1100px;\n  margin: auto;\n  padding: 20px;\n}\n\nbutton {\n  background-color: #177c45;\n  color: white;\n  border: none;\n  padding: 10px;\n  margin: 5px;\n  cursor: pointer;\n}\n/* hover significa que el botón cambia de color al pasar el ratón */\nbutton:hover {\n  background-color: #7e550a;\n}\n\n/* CABECERA */\n\n.cabecera {\n  background-color: #1e293b;\n  color: white;\n}\n\n.cabecera-interior {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.marca {\n  color: white;\n  font-size: 24px;\n  text-decoration: none;\n}\n\n/* BIENVENIDA */\n\n.bienvenida {\n  background-color: #1e3a5f;\n  color: white;\n  padding: 20px;\n  margin: 20px 0;\n}\n\n.sobrelinea {\n  font-size: 12px;\n}\n\n/* PROMOCIONES */\n\n.promociones {\n  background-color: white;\n  color: #243447;\n  padding: 15px;\n  margin-top: 20px;\n}\n\n#promocion {\n  margin-top: 15px;\n}\n\n/* CATÁLOGO Y CARRITO  en columnas*/\n\n.distribucion {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 20px;\n}\n\n.productos,\n.carrito {\n  background-color: white;\n  padding: 20px;\n}\n\n.encabezado {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n/* TARJETAS */\n\n.catalogo {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 15px;\n}\n\n.tarjeta {\n  background-color: #f8fafc;\n  border: 1px solid #ddd;\n  padding: 15px;\n}\n\n.icono-producto {\n  font-size: 35px;\n}\n\n.precio {\n  color: green;\n  font-weight: bold;\n}\n\n/* CARRITO */\n\n.total {\n  display: flex;\n  justify-content: space-between;\n  border-top: 1px solid #ddd;\n  margin-top: 20px;\n  padding: 15px 0;\n}\n\n/* PIE DE PÁGINA */\n\n.pie {\n  text-align: center;\n  padding: 20px;\n}\n\n/* MÓVILES */\n\n@media (max-width: 700px) {\n  .distribucion,\n  .catalogo {\n    grid-template-columns: 1fr;\n  }\n}\n","materiales/javascript/variables/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// let se utiliza cuando el valor puede cambiar.\nlet nombre = \"Ana\";\nlet edad = 18;\n\n// const se utiliza cuando el valor no cambiará.\nconst ciudad = \"Madrid\";\nconst curso = \"JavaScript\";\n\ndocument.getElementById(\"nombre\").textContent = nombre;\ndocument.getElementById(\"edad\").textContent = edad;\ndocument.getElementById(\"ciudad\").textContent = ciudad;\ndocument.getElementById(\"curso\").textContent = curso;\ndocument.getElementById(\"mensaje\").textContent = `¡Hola, ${nombre}! Tienes ${edad} años y estás aprendiendo ${curso}.`;\n\n// Parte 2: prompt permite pedir un dato al usuario.\nconst nombreUsuario = prompt(\"¿Cómo te llamas?\");\nconst saludo = document.getElementById(\"saludo\");\n\nif (nombreUsuario && nombreUsuario.trim()) {\n  saludo.textContent = `¡Encantado de conocerte, ${nombreUsuario.trim()}!`;\n} else {\n  saludo.textContent = \"No has escrito ningún nombre.\";\n}\n\n/*\n// Parte 3: leemos el valor escrito en cada input.\nconst formulario = document.getElementById(\"formulario-datos\");\nconst resultadoFormulario = document.getElementById(\"resultado-formulario\");\n\nformulario.addEventListener(\"submit\", (evento) => {\n  evento.preventDefault();\n\n  const nombreInput = document.getElementById(\"nombre-input\").value;\n  const edadInput = document.getElementById(\"edad-input\").value;\n  const ciudadInput = document.getElementById(\"ciudad-input\").value;\n\n  resultadoFormulario.textContent = `Te llamas ${nombreInput}, tienes ${edadInput} años y vives en ${ciudadInput}.`;\n});\n*/\n\r\n","materiales/javascript/variables/ejercicio1.html":"<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Actividad 1 | Variables</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n    <script src=\"app.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <a class=\"volver\" href=\"../index.html\">← Volver a la portada</a>\n      <h1>Actividad 1: Declarar variables</h1>\n      <p class=\"intro\">En esta actividad usamos <code>let</code> para datos que pueden cambiar y <code>const</code> para los que permanecen fijos.</p>\n\n      <section>\n        <h2>Mis datos</h2>\n        <p>Nombre: <span id=\"nombre\"></span></p>\n        <p>Edad: <span id=\"edad\"></span> años</p>\n        <p>Ciudad: <span id=\"ciudad\"></span></p>\n        <p>Curso: <span id=\"curso\"></span></p>\n      </section>\n\n      <p id=\"mensaje\" aria-live=\"polite\"></p>\n\n      <section>\n        <h2>Parte 2: Usar prompt</h2>\n        <p>Escribe tu nombre en la ventana que aparece.</p>\n        <p id=\"saludo\" aria-live=\"polite\"></p>\n      </section>\n\n      <!--\n      <section>\n        <h2>Parte 3: Usar inputs</h2>\n        <p>Completa tus datos y pulsa el botón.</p>\n\n        <form id=\"formulario-datos\">\n          <label for=\"nombre-input\">Nombre</label>\n          <input id=\"nombre-input\" type=\"text\" required>\n\n          <label for=\"edad-input\">Edad</label>\n          <input id=\"edad-input\" type=\"number\" min=\"1\" required>\n\n          <label for=\"ciudad-input\">Ciudad</label>\n          <input id=\"ciudad-input\" type=\"text\" required>\n\n          <button type=\"submit\">Mostrar mis datos</button>\n        </form>\n\n        <p id=\"resultado-formulario\" aria-live=\"polite\"></p>\n      </section>\n      -->\n    </main>\n  </body>\n</html>\n","materiales/javascript/variables/style.css":"body {\n    font-family: Arial, sans-serif;\n    margin: 0;\n    min-height: 100vh;\n    display: grid;\n    place-items: center;\n    background: #f7df1e;\n}\n\nmain {\n    width: min(90%, 500px);\n    padding: 32px;\n    text-align: center;\n    background-color: white;\n    border-radius: 12px;\n    box-shadow: 0 8px 20px rgba(0, 0, 0, .14);\n}\n\n.intro {\n    line-height: 1.5;\n}\n\nsection {\n    margin: 24px 0;\n    padding: 16px;\n    text-align: left;\n    background: #fff8d8;\n    border-radius: 8px;\n}\n\n/* Estilos de la parte 3: formulario con inputs.\nform {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    text-align: left;\n}\n\ninput,\nbutton {\n    padding: 10px;\n    font: inherit;\n    border-radius: 6px;\n}\n\ninput {\n    border: 1px solid #aaa;\n}\n\nbutton {\n    margin-top: 8px;\n    color: #fff;\n    cursor: pointer;\n    background: #0056b3;\n    border: 0;\n}\n\n#resultado-formulario {\n    margin-bottom: 0;\n    font-weight: bold;\n}\n*/\n\n#mensaje {\n    font-size: 1.2rem;\n    margin: 24px 0;\n    font-weight: bold;\n}\n\n.volver {\n    color: #0056b3;\n    display: inline-block;\n    margin-bottom: 12px;\n}\n","materiales/js-clases-avante/dado/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction lanzarDado() {\n    let resultado = Math.floor(Math.random() * 6) + 1;\n    if (resultado === 6) {\n        document.getElementById(\"resultado\").textContent =\n            `¡Has sacado un 6! Has ganado 🎖️🎖️🎖️`;\n         \n\n    } else {\n        document.getElementById(\"resultado\").textContent =\n            `Has sacado un ${resultado}. ¡Inténtalo otra vez!`;\n    }\n\n \nreturn resultado;\n\n  \n    \n}\n\nfunction actualizarHistorial(resultado) {\n    let historial = document.getElementById(\"historial\");\n    historial.textContent += ` ${resultado}`;\n}\n\n\n\n\n\n\n\n\n\n\n   \r\n","materiales/js-clases-avante/dado/dado.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Lanzar el dado</title>\n    <script src=\"app.js\"></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n</head>\n<body>\n    <h1>Lanzar el dado</h1>\n    <img id=\"dado\" src=\"dado.png\" alt=\"Dado\" width=\"100\" height=\"100\">\n    <p>Tira el dado para ver qué número sale.</p>\n    <p>Ganarás si consigues un 6</p>\n    <p id=\"resultado\">Aquí aparecerá el resultado del lanzamiento.</p>\n    <p id=\"historial\">Historial de resultados: </p>   \n\n    <button onclick=\"lanzarDado()\">Lanzar dado</button>\n    <button onclick=\"actualizarHistorial(lanzarDado())\">Actualizar historial</button>\n    </body>\n    \n</html>","materiales/js-clases-avante/dado/styles.css":"body{\n    font-family: Arial, sans-serif;\n    text-align: center;\n    margin: auto;\n    background-color: #f0f0f0;\n    border: 4px solid #ccc;\n    width:70%;\n}\n\nh1{\n    color: #333;\n    font-size: 2em;\n}\n\nbutton{\n     \n     background-color: #16c207;\n    margin: 10px 0;\n     padding: 10px 20px;\n     font-size: 1em;\n     cursor: pointer;\n     border-radius: 5px;\n}\n\np{\n    font-size: 1.2em;\n    color: #666;\n}\n\nimg{\n    margin-top: 20px;\n    width: 100px;\n    height: 100px;\n}\n\n#resultado{\n    font-size: 1.5em;\n    font-weight: bold;\n    margin-top: 20px;\n}","materiales/js-clases-avante/ejercicio1/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nlet nombre = \"Ana\";\nlet edad = 18;\nlet ciudad = \"Madrid\";\n\n\nconsole.log (`Me llamo ${nombre}, tengo ${edad} años y vivo en ${ciudad}.`);\n\nlet hola = (`Hola, me llamo ${nombre}, tengo ${edad} años y vivo en ${ciudad}.`);\n\ndocument.getElementById(\"hola\").textContent = hola;\n\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio1/ejercicio1.html":"<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Actividad 1 | Variables</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <a class=\"volver\" href=\"../index.html\">← Volver a la portada</a>\n      <h1>Actividad 1: Declarar variables</h1>\n      <p>Se mostrará un saludo con los datos de la persona.</p>\n\n      <p>El saludo se mostrará a continuación:</p>\n\n      <p id=\"hola\" aria-live=\"polite\"></p>\n\n    \n      <!--\n      <section>\n        <h2>Parte 3: Usar inputs</h2>\n        <p>Completa tus datos y pulsa el botón.</p>\n\n        <form id=\"formulario-datos\">\n          <label for=\"nombre-input\">Nombre</label>\n          <input id=\"nombre-input\" type=\"text\" required>\n\n          <label for=\"edad-input\">Edad</label>\n          <input id=\"edad-input\" type=\"number\" min=\"1\" required>\n\n          <label for=\"ciudad-input\">Ciudad</label>\n          <input id=\"ciudad-input\" type=\"text\" required>\n\n          <button type=\"submit\">Mostrar mis datos</button>\n        </form>\n\n        <p id=\"resultado-formulario\" aria-live=\"polite\"></p>\n      </section>\n      -->\n    </main>\n\n\n  </body>\n</html>\n","materiales/js-clases-avante/ejercicio1/styles.css":"#hola {\n    color: blue;\n    font-weight: bold;\n    background-color: lightgray;\n}\n\nmain{\n    background-color: #f0f0f0;\n    padding: 20px;\n    width:80%;\n    border: 1px solid #ccc;\n    margin: 0 auto;\n    justify-content: center;\n    \n}","materiales/js-clases-avante/ejercicio10/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/*Una persona quiere decidir qué actividad puede hacer según el dinero \nque tiene y si hace buen tiempo.*/\n/*2. Primera parte: tomar una decisión con if\nCompleta un condicional que asigne un valor a tipoPlan siguiendo estas reglas:\nCondición\tValor de tipoPlan\nTiene 20 € o más y hace buen tiempo\t\"excursion\"\nTiene 10 € o más, pero no cumple la condición anterior\t\"cine\"\nTiene menos de 10 €\t\"casa\"\nPara resolverlo, deben utilizar if, else if, else, >= y &&.*/\n\nlet tipoPlan;\nlet dinero = 15;\nlet buenTiempo = true;\n\nif (dinero >= 20 && buenTiempo) {\n    tipoPlan = \"excursion\";\n    console.log(tipoPlan);\n} else if (dinero >= 10) {\n    tipoPlan = \"cine\";\n    console.log(tipoPlan);\n\n} else {\n    tipoPlan = \"casa\";\n    console.log(tipoPlan);\n}\n\nswitch(tipoPlan){\n    case \"excursion\":\n        console.log (\"Te vas de excursion\");\n        document.getElementById(\"actividad\").textContent = \"Te vas de excursion\";\n        break;\n    case \"cine\":\n        console.log(\"Vas al cine\");\n        document.getElementById(\"actividad\").textContent = \"Vas al cine\";\n        break;\n    case \"casa\":\n        console.log(\"Te quedas en casa\");\n        document.getElementById(\"actividad\").textContent = \"Te quedas en casa\";\n        break;\n}\r\n","materiales/js-clases-avante/ejercicio10/ejercicio.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Practicando if y switch</title>\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Actividad recomendada</h1>\n    <p id=\"actividad\"></p>\n</body>\n</html>","materiales/js-clases-avante/ejercicio10/style.css":"","materiales/js-clases-avante/ejercicio11/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// // let condicion=1;\n\n// // while (condicion<6){\n\n// //     console.log (\"soy menor a seis\");\n// //     console.log(condicion);\n// //     condicion=condicion+1;// actualizo el contador \n// //     //condicion++ condicion+=2\n\n// // }\n\n// // /*adivinar un numero aleatorio, el usuario tiene que introducir un número hasta que adivine el número aleatorio*/\n// // let numeroAleatorio=8;\n// // let numeroIntroducido=Number(prompt(\"Introduce un número menor que 10\"));\n\n\n// // while (numeroIntroducido!=numeroAleatorio){\n// //     numeroIntroducido=Number(prompt(\"Introduce un número menor que 10\"));\n// //    if (numeroIntroducido===numeroAleatorio){\n// //        alert(\"Has adivinado el número\");\n// //    }\n// // }\n\n// // /*bucle while para saludar tres veces*/\n\n// // let saludo=0;\n// // /*saludo entra en el bucle cumple la condicion*/\n// // while (saludo<3){ \n// // /*ejecuta el codigo del bucle*/\n// //     console.log(\"Hola\");\n    \n// // /*saludo se actualiza para que no sea infinito el bucle y sólo salude 3 veces*/\n// //     saludo=saludo+1; /*saludo++*/\n\n// //     console.log (\"soy saludo actualizado y valgo: \"+saludo);\n\n// // }\n\n// // /*hacer un bucle while que cuente del 1 al 5 y lo muestre por consola*/\n\n// // /*declaracion e iniciliacion de variable contador*/\n// // let contador=1;\n// // /*condicion del bucle ¿hasta cuando se va a ejecutar el bucle?*/\n// // while(contador<=5){\n\n// //     console.log(contador);\n// //     /*actualizacion del contador que posibilidades tengo de terminar el bucle*/\n// //     contador++; /*contador=contador+1*/\n\n    \n// // }\n\n// // // /*usa el bucle for y cuenta del 1 al 7*/\n\n// // for (let i=1; i<=7; i++){\n// //     console.log(i);\n// // }\n\n// // let i=1;\n// // while (i<=7){\n// //     console.log(i);\n// //     i++; \n// // }\n\n// /*mostrar 2, 4, 6, 8 y 10. Escribe un for que empiece en 2 y avance de dos en dos.*/\n\n// // for (let i=2; i<=10; i+=2){\n// //     console.log(i);\n// // }\n\n// /*Con numero = 10 y condición numero < 5, ¿cuántas veces se ejecutará el bucle while?*/\n\n// // let numero=10;\n\n// // do{\n// //     console.log (\"hola soy el bucle do while \" + numero);    \n// //     numero++;\n// // } while(numero<5);\n\n// /*Crea un programa en JavaScript que recorra los números del 1 al 20 y:\n// - Compruebe si cada número es par.\n// - Muestre en consola los números pares.\n// - Cuente cuántos números pares se han encontrado.\n// - Muestre el resultado final.*/\n\n// for (let numero=1; numero<20; numero++){    \n   \n\n//     /*este condicional comprueba si el número es par, si lo es lo muestra por consola*/\n\n//     if (numero % 2 === 0) {\n//                 console.log(\"este es un numero par: \" + numero);\n//             }   \n            \n            \n// }   /*el bucle termina en esta llave*/\n\n\n/*quiero un programa que muestre si las primeras diez personas pueden entrar\nsólo pueden entrar si tienen 18 años o más*/\n/*estas personas su edad se va a multiplicar por 3 en cada persona, \nla primera tiene un año*/\nlet edad=1;\n\nfor (let persona=1; persona<=10; persona++){\n    edad=edad*3;\n    console.log(\"la edad de la persona \" + persona + \" es: \" + edad);\n    if (edad>=18){\n        console.log(\"la persona \" + persona + \" puede pasar\");\n    }else{\n        console.log(\"la persona \" + persona + \" no puede pasar\");\n    }   \n}\n\n\n\n\n/*quiero un programa que muestre si las primeras diez personas pueden entrar*/\nconst mensaje = document.getElementById(\"mensaje\");\nlet puedenPasar = 0;\n \nfor (let persona = 1; persona <= 10; persona += 1) {\n    \n  const edad = Number(prompt(\"Persona \" + persona + \": escribe tu edad\"));\n \n  if (edad >= 18) {\n    alert(\"La persona \" + persona + \" puede pasar.\");\n    puedenPasar += 1;/*el numero de personas que pueden pasar xq tienen mas de 18*/\n    console.log(\"La persona \" + persona + \" puede pasar.\");\n  }else{\n    console.log(\"La persona \" + persona + \" no puede pasar.\");\n    alert(\"La persona \" + persona + \" no puede pasar.\");\n  }\n}\n \nif (puedenPasar === 10) {\n  mensaje.textContent = \"Las 10 personas pueden entrar.\";\n} else {\n  mensaje.textContent = \"Solo pueden entrar \" + puedenPasar + \" de 10.\";\n \n}\n\n \n\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio11/ejercicio11.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Aprendiendo bucles</title>\n    <script src=\"app.js\" defer></script>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n    \n</head>\n<body>\n<h1> Aprendiendo bucles</h1>\n<h2> El bucle while</h2>\n<p> El bucle while se utiliza para repetir un bloque de código \n    mientras una condición sea verdadera.</p>\n\n<p> La sintaxis del bucle while es la siguiente:</p>\n<pre>\n    while (condición) {\n        // bloque de código a ejecutar mientras la condición sea verdadera\n        //actualización de la condición\n    }\n\n</pre>\n<p>Debemos pensar que el bucle while se ejecuta mientras la condición sea verdadera.\nPor lo que debemos asegurarnos de que la condición cambie en algún momento para evitar un bucle infinito.\n</p>\n\n<p> De 10 personas pueden pasar: <span id=mensaje>   </span></p>\n\n\n\n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio11/styles.css":"body {\n    font-family: Arial, sans-serif;\n    background-color: #f0f0f0;\n    margin: 4rem;\n    padding: 0;\n}\n\nh1{\n    color: #333;\n    text-align: center;\n    margin-top: 20px;\n}\n\npre {\n    background-color: #e0e0e0;\n    padding: 10px;\n    border-radius: 5px;\n    overflow-x: auto;\n}\n\n","materiales/js-clases-avante/ejercicio12/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction saludar(nombre) {\n  return  \"Hola, \" + nombre + \", soy la función crearSaludo\";\n}\n\nconsole.log(crearSaludo(\"Maria\"));\n\n\n /*crear un boton en html que llame a una funcion que muestre la edad. La edad se la pasas \n por parammetro al llamar a la funcion*/\n\n\nfunction edad() {\n\n  let  edades = document.getElementById(\"edad\").value;\n\n    document.getElementById(\"mostrarEdad\").textContent =\n\n           \"Mi edad es: \" + edades;\n\n           if(edades < 18){\n               document.getElementById(\"mostrarEdad\").textContent += \" (Eres menor de edad)\";\n           }else{\n               document.getElementById(\"mostrarEdad\").textContent += \" (Eres mayor de edad)\";\n           }\n\n\n\n}\n\nconsole.log (edades);\n\n    function mostrarDatos() {\n\n        let nombreDatos= saludar();\n        let edadDatos= edad();\n\n    \n        document.getElementById(\"datos\").textContent = \"Nombre: \" + nombreDatos + \", Edad: \" + edadDatos;\n    }\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio12/ejercicio12.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Aprendiendo funciones onclick</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1> Aprendiendo funciones onclick</h1>\n    <p> Vamos a crear una funcion y la vamos a llamar con un botón</p>\n\n    <label for=\"nombre\">Escribe tu nombre</label>\n   <input type=\"text\" id=\"nombre\" placeholder=\"Escribe tu nombre\">\n    <button onclick=\"saludar()\"> Haz click aquí para ver la función saludar</button>\n    <p> Soy la función saludar</p>\n     <span id=\"saludo\"></span>\n\n     <p>Aqui voy a mostrar tres veces el saludo</p>\n     <span id=\"saludoRepetido\"></span>\n   \n    <label for=\"edad\">Escribe tu edad</label>\n   <input type=\"number\" id=\"edad\" placeholder=\"Escribe tu edad\">   \n   \n\n\n    <button onclick=\"edad()\"> Haz click para ver la edad</button>\n    <p> Soy la función edad </p>   \n  <span id=\"mostrarEdad\"></span>\n\n  <button onclick=\"mostrarDatos()\"> Mostrar datos</button>\n  <p> Soy la función mostrarDatos </p>\n  <span id=\"datos\"></span>\n\n  \n\n\n</body>\n</html>","materiales/js-clases-avante/ejercicio12/styles.css":"\nbody {\n    font-family: Arial, sans-serif;\n    background-color: #f4f6f8;\n    color: #333;\n    padding: 30px;\n    max-width: 650px;\n    margin: 0 auto;\n}\n\nh1 {\n    color: blue;\n    text-align: center;\n}\n\np {\n    line-height: 1.6;\n    margin-bottom: 20px;\n}\n\nlabel {\n    display: block;\n    margin-top: 20px;\n    margin-bottom: 5px;\n}\n\ninput {\n    padding: 10px;\n    border: 1px solid #ccc;\n    border-radius: 5px;\n    width: 90%;\n}\n\nbutton {\n    display: block;\n    background-color: blue;\n    color: white;\n    padding: 12px 20px;\n    border: none;\n    border-radius: 5px;\n    margin: 20px auto;      \n    cursor: pointer;\n    text-align: center;\n}\n\nbutton:hover {\n    background-color: green;\n}\n\nspan {\n    background-color: #c4cccc;  \n    display: block;\n    font-weight: bold;\n    color: rgb(7, 45, 110);\n    margin-top: 10px;\n}\n/*\n#saludoRepetido {\n    white-space: pre-line;\n}*/","materiales/js-clases-avante/ejercicio13/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/*<label>Nombre <input id=\"nombre\" type=\"text\"></label>\n  <label>Nota <input id=\"nota\" type=\"number\"></label>\n  <button onclick=\"guardarAlumno()\">Guardar alumno</button>\n  <p id=\"contador\">Alumnos registrados: 0</p>\n  <button onclick=\"mostrarNotas()\">Mostrar notas</button>\n  <p id=\"mensaje\"></p>\n  <p id=\"resultado\"></p>*/\n/*declara los arrays para almacenar los alumnos y sus notas*/\nlet alumnos = [];\nlet notas=[2,2,2,5,5];\nnotas.splice(1,2,3);\nconsole.log (\"soy notas con splice\", notas);\n\n\n\n\n    let nombre= document.getElementById(\"nombre\").value;\n    let nota= document.getElementById(\"nota\").value;\n    alumnos.push(nombre);\n    notas.push(nota);\n    /*mostrar la cantidad de alumnos que tenemos en el array alumnos*/\n    document.getElementById(\"contador\").textContent = \"Alumnos registrados: \" + alumnos.length;\n\n\n\nfunction mostrarNotas() {\n    let mensajeConNotas = \"\";\n    for (let i = 0; i < alumnos.length; i++) {\n        mensajeConNotas += alumnos[i] + \": \" + notas[i] + \" \";\n    }\n    document.getElementById(\"mensaje\").textContent = mensajeConNotas;\n}\n\n\n\r\n","materiales/js-clases-avante/ejercicio13/ejercicio13.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Métodos propios de JavaScript</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <h1>Arrays</h1>\n    \n<main class=\"cuaderno\">\n  <h1>Cuaderno de notas</h1>\n  <!-- Formulario para ingresar alumnos -->\n  <label>Nombre <input id=\"nombre\" type=\"text\"></label>\n  <label>Nota <input id=\"nota\" type=\"number\"></label>\n  <button onclick=\"guardarAlumno()\">Guardar alumno</button>\n  <p id=\"contador\">Alumnos registrados: 0</p>\n  <button onclick=\"mostrarNotas()\">Mostrar notas</button>\n  <p id=\"mensaje\"></p>\n  <p id=\"resultado\"></p>\n\n  <!-- Sección para mostrar las frutas del array arrayFrutas -->\n\n  <h2>Frutas 🍒🍒🍒</h2>\n<label for=\"agregarFruta\">Escribe una fruta: </label>\n<input id=\"agregarFruta\" type=\"text\" placeholder=\"Escribe una fruta\">\n<button onclick=\"agregarFruta()\">Agregar fruta</button>\n\n  <p id=\"frutas\"></p>\n  <button onclick=\"mostrarFrutas()\">Mostrar frutas</button>\n\n</main>\n\n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio13/styles.css":".cuaderno {\n  background-color: white;\n  color: #17325c;\n  padding: 24px;\n  margin: 24px auto;\n  border: 1px solid #d5dce8;\n  border-radius: 12px;\n  width: 90%;\n  max-width: 540px;\n  text-align: center;\n}\n.cuaderno input, .cuaderno button {\n  padding: 10px;\n  margin: 6px;\n  border: 1px solid #17325c;\n  border-radius: 6px;\n}\n#resultado { white-space: pre-line; }","materiales/js-clases-avante/ejercicio14/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction lanzarDado() {\n    let resultado = Math.floor(Math.random() * 6) + 1;\n    if (resultado === 6) {\n        document.getElementById(\"resultado\").textContent =\n            `¡Has sacado un 6! Has ganado 🎖️🎖️🎖️`;\n         \n\n    } else {\n        document.getElementById(\"resultado\").textContent =\n            `Has sacado un ${resultado}. ¡Inténtalo otra vez!`;\n    }\n\n \nreturn resultado;\n\n  \n    \n}\n\nfunction actualizarHistorial(resultado) {\n    let historial = document.getElementById(\"historial\");\n    historial.textContent += ` ${resultado}`;\n}\n\n\n\n\n\n\n\n\n\n\n   \r\n","materiales/js-clases-avante/ejercicio14/dado.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Ejercicio Dado</title>\n</head>\n<body>\n    <h1>Ejercicio dado para practicar funciones, condicionales y arrays</h1>\n\n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio14/styles.css":"","materiales/js-clases-avante/ejercicio15/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// // /*bucle for of\n// // for (let precio of precios) {\n// //     console.log(precio);\n// // }*/\n\n// // /*bucle for each recorre cada elemento del array\n// // y ejecuta la función para cada uno de ellos */\n// // // precios.forEach(function(precio) {\n// // //     let precioIva = precio * 1.21;\n// // //     console.log(precioIva);\n// // // });\n\n// // // /*array para almacenar los precios con IVA que nace fuera\n// // // de la función para poder acceder a estos datos\n// // // fuera del bucle for each */\n// // // let preciosIva = [];\n// // // /*bucle for each para calcular el IVA\n// // // y almacenar los precios con IVA en el nuevo array preciosIva */\n// // // precios.forEach(precio => {\n// // //     let precioIva = precio * 1.21;\n// // //     preciosIva.push(precioIva);\n// // //     console.log(precioIva);\n// // // });\n// // // console.log (\"array original de precios sin Iva: \"+ precios);\n// // // console.log(\"Precios con IVA:\" + preciosIva);\n// // /*declaración de arrays */\n// // //\n\n// // // let preciosIva=precios.map(precio => precio * 1.21);\n\n// // // console.log(\"array original de precios sin Iva: \"+ precios);\n// // // console.log(\"Precios con IVA:\" + preciosIva);\n// // /*array con descuento del 15% */\n// // let precios= [10,20,30,40];\n// // // let preciosDescuento=precios.map(precio => precio * 0.85);\n\n// // // console.log(\"array original de precios sin descuento: \" + precios);\n// // // console.log(\"Precios con descuento del 15%: \" + preciosDescuento);\n\n// // // let productosCaros=precios.filter(precio => precio > 25);\n// // // console.log(\"Productos caros (precio > 25): \" + productosCaros);\n// // /*busca un elemento en el array y te muestra el primero que encuentra */\n// // let producto30=precios.find(precio => precio === 30);\n// // console.log(\"Producto con precio 30: \" + producto30);\n// // let producto45=precios.find(precio => precio === 45);\n// // console.log(\"Producto con precio 45: \" + producto45);\n// // /*incluye devuelve true o false*/\n// // let producto20=precios.includes(20);\n// // console.log(\"Producto con precio 20: \" + producto20);\n// // /*acumulador de precios */\n// // const total=precios.reduce((suma, precio) => suma + precio, 0);\n// // console.log(\"Total de precios: \" + total);\n\n// let carrito = [\"pan\", \"leche\", \"huevos\"];\n// let eliminado = carrito.splice(1, 2);\n// console.log(\"Elemento eliminado: \" + eliminado);\n// console.log(\"Carrito actual: \" + carrito);\n// /*carrito=[\"pan\"];*/\n// carrito.splice(1, 0, \"mantequilla\", \"queso\", \"tomate\");\n// console.log(\"Carrito actualizado: \" + carrito);\n// //carrito[\"pan\",\"mantequilla\",\"queso\",\"tomate\"]\n// //meter harina detrás de mantequilla\n// carrito.splice(2, 1, \"harina\");\n// console.log(\"Carrito actualizado: \" + carrito);\nlet tareas = [\n  \"Estudiar JavaScript\",\n  \"Hacer ejercicios\",\n  \"Repasar arrays\"\n];\n/*Muestra las tareas numeradas: \"Tarea 1: ...\", \"Tarea 2: ...\".\nforEach() se utiliza para recorrer cada elemento del array \ny mostrarlo con su índice.\n*/\ntareas.forEach((tarea, posicion) => {\n  console.log(\"Tarea\"+(posicion) + \":\"+tarea);\n});\n\n\r\n","materiales/js-clases-avante/ejercicio15/arrays.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Métodos arrays</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio15/styles.css":"","materiales/js-clases-avante/ejercicio16/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/* Definición de un objeto */\nfunction calcularTotal() {\n  return this.precio * this.cantidad;\n}\n\nconst falda ={\n    nombre: \"Falda\",\n    precio: 25,\n    disponible: true,\n    cantidad: 3,\n    talla:[\"s\",\"m\",\"l\"],\n    calcularTotal: calcularTotal\n   };\n\n   console.log(\"soy el precio total de la falda: \" + falda.calcularTotal()  );\n\nconst pantalon = {\n    nombre: \"Pantalón\",\n    precio: 40,\n    disponible: true,\n    cantidad: 2,\n    calcularTotal: calcularTotal\n   };\n\nconsole.log(\"soy el precio total del pantalón: \" + pantalon.calcularTotal());\n// console.log(producto);\n\n// producto.calcularTotal();\n// console.log(producto.calcularTotal( ));\n\n\n\n// console.log(producto);\n// /* Accediendo a las propiedades del objeto */\n// producto.nombre;\n// producto.precio;\n// producto.disponible;\n// console.log (producto.nombre);\n// console.log (producto.precio);\n// console.log (producto.disponible);\n// /*Añadiendo una nueva propiedad al objeto */\n// producto.talla=[\"S\", \"M\", \"L\", \"XL\"];\n// console.log(producto.talla);\n// /*Modificar una propiedad del objeto */\n// producto.precio=30;\n// console.log(producto.precio);\n// /*Borrar una propiedad del objeto */\n// delete producto.disponible;\n// console.log(producto);\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio16/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Objetos de Javascript</title>\n     <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    \n</head>\n<body>\n    <h1>Hoy aprendemos Objetos de Javascript</h1>\n    <h2>Ejemplos de Objetos</h2>\n</body>\n</html>","materiales/js-clases-avante/ejercicio16/styles.css":"","materiales/js-clases-avante/ejercicio17/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// const productos = [\n//   { nombre: \"Ratón\", precio: 15, cantidad: 2 },\n//   { nombre: \"Teclado\", precio: 30, cantidad: 3 },\n//   { nombre: \"Monitor\", precio: 150, cantidad: 4 }\n// ];\n// for (const producto of productos) {\n//  console.log(\"este es el nombre de producto:\"+ producto.nombre);\n//  console.log (`este es el precio del producto: ${producto.precio} , este es la cantidad: ${producto.cantidad}`)\n// }\n\n// let contador = 0;\n// for (const producto of productos){\n//     if (producto.precio >20) {\n//         contador++;\n//     }\n// }\n// console.log(\"Cantidad de productos con precio mayor a 20: \" + contador);\n// /*busca el primer producto con precio mayor a 20 */\n// const encontrado= productos.find(producto => producto.precio > 20);\n// console.log(encontrado);\n// /*busca todos los productos con precio mayor a 20 y nos devuelve un array con ellos */\n// const productosCaros= productos.filter(producto => producto.precio > 20);\n// console.log(productosCaros);\n// for (const producto of productosCaros) {\n//     console.log(\"Producto caro: \" + producto.nombre);\n// }\n\n// productos.push({\n//   nombre: \"Impresora\",\n//   precio: 90,\n//   cantidad: 2\n\n// });\n// console.log(productos);\n\n\n// /*for in loop para mostrar las propiedades y valores del tercer producto */\n// for (const propiedad in productos[2]) {\n//   console.log(\"soy la propiedad y el valor: \" + propiedad + \": \" + productos[2][propiedad]);\n// }\n// /*aprendemos object key, object values y object entries */\n\nlet falda = {\n  nombre:\"Falda\",\n  cantidad:10,\n  precio: 25\n}\n/*nos muestra las propiedades del objeto */\nconsole.log(Object.keys(falda));\n\n/*nos muestra los valores del objeto */\nconsole.log(Object.values(falda));\n\n/*nos muestra los pares [propiedad, valor] del objeto */\nconsole.log(Object.entries(falda));\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio17/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Arrays de objetos</title>\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Arrays de objetos</h1>\n    <p>Hoy aprendemos a meter objetos dentro de un array</p>\n\n</body>\n</html>","materiales/js-clases-avante/ejercicio17/styles.css":"","materiales/js-clases-avante/ejercicio18/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n\nlet muchosParrafos=document.querySelectorAll(\".mensaje\");\n\nconsole.log(muchosParrafos);\n\nmuchosParrafos.forEach(miParrafito=>{\n\n    miParrafito.textContent=\"soy un parrafo capturado por un querySelectorAll\"\n\n\n})\n\nlet hora= new Date().getHours() + \":\" \n+ new Date().getMinutes() + \":\" \n+ new Date().getSeconds() + \" .\" \n+ new Date().getDate() + \"/\" \n+ (new Date().getMonth() + 1) \n+ \"/\" + new Date().getFullYear() + \" aqui soy UTC:\" \n+ new Date().toUTCString();\n\nif(hora < \"12:00\")\n    document.getElementById(\"saludo\").textContent = \n\"Buenos días. La hora actual es: \" + hora \nelse if(hora < \"18:00\")\n    document.getElementById(\"saludo\").textContent = \n\"<strong> Buenas tardes. La hora actual es: \" + hora + \"</strong>\";\nelse\n    document.getElementById(\"saludo\").textContent = \n\"Buenas noches. La hora actual es: \" + hora;\n\n/* Función para mostrar la ficha del curso seleccionado */\n\nfunction mostrarCurso(opcion) {\n  const ficha = document.getElementById(\"ficha\");\n\n  if (opcion === \"html\") {\n    ficha.innerHTML = \"<h3>HTML esencial</h3>\" +\n    \"<p>Aprende a estructurar páginas web.</p>\" +\n    \"<p>Este curso es fundamental para cualquier desarrollador web.</p>\";\n  } else {\n    ficha.innerHTML = \"<h3>JavaScript esencial</h3>\" +\n    \"<p>Haz que tus páginas respondan.</p>\";\n  }\n}\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio18/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Trabajando el DOM</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <h1>Trabajando con el DOM</h1>\n    <h2>Aprendiendo selectores del Dom</h2>\n    <!-- Párrafo con el id \"saludo\" -->\n    <p id=\"saludo\">hola soy un mensaje en saludo</p>\n    <!-- Párrafos con la clase \"mensaje\" -->\n    <p class=\"mensaje\">Hola</p>\n    <p class=\"mensaje\">Hola</p>\n    <p class=\"mensaje\">Hola</p>\n    <div class=\"curso\">\n    <button type=\"button\" onclick=\"mostrarCurso('html')\">Curso HTML</button>\n    <button type=\"button\" onclick=\"mostrarCurso('javascript')\">Curso JavaScript</button>\n</div>\n<section id=\"ficha\"></section>    \n</body>\n</html> ","materiales/js-clases-avante/ejercicio18/styles.css":".mensaje{\n    background-color:rgb(121, 175, 121);\n    padding: 10px;\n    font-size: 16px;\n    margin:10px 10px;\n    \n}\n\n.curso{\n    margin: 20px 0;\n    background-color: rgb(225, 147, 212);\n}\n\n","materiales/js-clases-avante/ejercicio2/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/*tres variables inciializadas*/\n\nlet pelicula;\nlet director;\nlet anyo;\n\n/*asignamos valores a las variables*/\npelicula = \"Coco\";\ndirector = \"Lee Unkrich\";\nanyo = 2017;\n\n// muestra la información de la película en la consola y en el documento HTML\n\nconsole.log( \"La película \" + pelicula + \" fue dirigida por \" + director + \" y se estrenó en \" + anyo + \".\");\n\n// muestra la información de la película en el documento HTML con template literals\n\ndocument.getElementById(\"informacion\").textContent = (`La película ${pelicula} fue dirigida por ${director} y se estrenó en ${anyo}.`);\n\n// muestra la información de la película en el documento HTML con concatenación de cadenas\n\ndocument.getElementById(\"informacion\").textContent=(\"La película \" + pelicula + \" fue dirigida por \" + director + \" y se estrenó en \" + anyo + \".\");\n\n\n\n\n\n\n\n\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio2/ejercicio2.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Ejercicio2 variables</title>\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <p id=\"informacion\"></p>\n\n    \n<script src=\"app.js\" ></script>\n</body>\n</html>","materiales/js-clases-avante/ejercicio2/styles.css":"","materiales/js-clases-avante/ejercicio3/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Lee el código de arriba abajo: se declaran los datos, se definen las funciones y al final se llama a la función que inicia la práctica.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nlet precio=25;\nlet cantidad=3;\nlet descuento=5;\n\n// operador de suma\nlet suma= precio+precio;\nconsole.log(suma);\n\n//operador resta\nlet resta=suma-precio;\nconsole.log(resta);\n\nresta= precio-descuento;\nconsole.log(resta); // resta ahora vale 20\n\n// operador multiplicación\nlet multiplicacion= precio*cantidad;\nconsole.log(multiplicacion); // multiplicacion ahora vale 75\n\n//operador de división\n let division= precio/cantidad;\nconsole.log(division); // division ahora vale 8.333333333333334\n\n// operador de módulo\nlet modulo= precio%cantidad;\nconsole.log(modulo); // resto de la división de precio entre cantidad\n\n// iva\n\nlet iva= (precio * 21) / 100; // precio * 0,21\niva= precio * 0.21; \nconsole.log(\"el precio con iva es: \" + iva); // iva ahora vale 5.25\n\nlet precioTotal= precio + iva;\nconsole.log(precioTotal); // precioTotal ahora vale 30.25\n\n\n//operadores de asignacion\n\nlet carrito=0;\ncarrito += 10; // carrito + 10 \ncarrito=carrito+10;\nconsole.log(carrito); // carrito ahora vale 10\n\ncarrito -= 5; // carrito - 5\nconsole.log(carrito); // carrito ahora vale 5\n\ncarrito= carrito-5;\n\nconsole.log(carrito); // carrito ahora vale 0\n\n\n\n\n\n\n\n\r\n","materiales/js-clases-avante/ejercicio3/ejercicio3.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Trabajando con operadores aritméticos</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <header>\n        <h1>Trabajando con operadores aritméticos</h1>\n    </header>\n</body>\n</html>","materiales/js-clases-avante/ejercicio3/styles.css":"","materiales/js-clases-avante/ejercicio4/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Lee el código de arriba abajo: se declaran los datos, se definen las funciones y al final se llama a la función que inicia la práctica.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// let a=7;\n// let b=\"7\";\n// let c= a<3;\n// console.log(c);\n\n// c=a<b;\n// console.log(c);\n\n// let d;\n// d= 7!==\"7\"; //esta evita las conversiones\n// console.log(d);//true\n\n// let e;\n\n// e= a===b;\n// console.log(e);//false\n// //fin de los operadores de comparación estricta\n\n// //comparadores logicos\n\n// let puedePasar;\n// let llave=true;\n// let permiso=false;\n// let jefe=true;\n\n// //puedePasar true si tiene la llave o el permiso\n\n// puedePasar= llave||permiso; //or alternativa\n// console.log(puedePasar);\n\n\n// puedePasar= (llave&&permiso)||jefe; \n// console.log(puedePasar);\n\n// let estaLloviendo = false;\n// let puedoSalirSinParaguas = !estaLloviendo;\n\n// console.log(puedoSalirSinParaguas); \n\n//ejercicios\n\n// let x=8>3;//true\n// console.log(x);\n\n// let y= 2<1;//false\n// console.log(y);\n\n// //Evalúa 5 >= 5 y 4 <= 3.\n// let z = 5 >= 5;\n// console.log(z);//true\n\n// let w = 4 <= 3;\n// console.log(w);//false\n\n//Compara \"10\" == 10 y \"10\" === 10. Observa la diferencia.\nlet a=\"10\";\n\nlet b= a + 5;\nconsole.log(b);\n\nlet c= a===b;\nconsole.log(c);\n\n//Compara 7 != \"7\" y 7 !== \"7\". negacion de la igualdad\nlet d = 7 != \"7\";\nconsole.log(d);//false\n\nlet e = 7 !== \"7\";\nconsole.log(e);//true\n\n\n\n\nlet esFestivo = true;\nlet esDomingo = false;\n\nlet puedoDescansar = !esFestivo || esDomingo;\nconsole.log(puedoDescansar);//false\n\r\n","materiales/js-clases-avante/ejercicio4/ejercicio.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>operadores de commparacion</title>\n    <script src=\"app.js\"></script>\n</head>\n<body>\n    <h1>Operadores de comparación</h1>\n</body>\n</html>","materiales/js-clases-avante/ejercicio5/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/* ===================================\n   1. DATOS DE LA COMPRA\n=================================== */\n\nconst precioPantalon = 30;\nconst cantidadPantalones = 2;\n\nconst precioCamiseta = 15;\nconst cantidadCamisetas = 1;\n\n// Calculamos el importe de los productos\nconst total = (precioPantalon * cantidadPantalones)\n            + (precioCamiseta * cantidadCamisetas);\n\n// Mostramos el resultado\nconsole.log(\"Total de productos:\", total);\n\ndocument.getElementById(\"total\").textContent = total;\n\n\n/* ===================================\n   2. GASTOS DE ENVÍO\n=================================== */\n\nconst gastosEnvio = 5;\n\nconst totalConEnvio = total + gastosEnvio;\n\nconsole.log(\"Total con envío:\", totalConEnvio);\n\ndocument.getElementById(\"totalConEnvio\").textContent = totalConEnvio;\n\n\n/* ===================================\n   3. DESCUENTO GENERAL\n=================================== */\n\n// Descuento si supera los 100 €\n// O si compra más de 3 artículos\n\nconst cantidadTotal = cantidadPantalones + cantidadCamisetas;\n\nconst descuento = total > 100 || cantidadTotal > 3;\n\nconsole.log(\"¿Tiene descuento?\", descuento);\n\ndocument.getElementById(\"descuento\").textContent = descuento;\n\n\n/* ===================================\n   4. DESCUENTO ADICIONAL\n=================================== */\n\n// Debe ser miembro del club Y comprar un viernes\n\nconst miembroClub = true;\nconst esViernes = true;\n\nconst descuentoAdicional = miembroClub && esViernes;\n\nconsole.log(\"¿Tiene descuento adicional?\", descuentoAdicional);\n\ndocument.getElementById(\"descuentoAdicional\").textContent = descuentoAdicional;\n\nconst envio = document.getElementById(\"envio\");\n\nlet premium = true;\nlet bloqueoDireccion = false;\n\nif ((premium || total >= 50) && !bloqueoDireccion) {\n  envio.textContent = \"¡Tu compra tiene envío gratuito!\";\n} else {\n  envio.textContent = \"Lo siento, tu envío no es gratis.\";\n}  \n\r\n","materiales/js-clases-avante/ejercicio5/ejercicio5.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Practicando operadores</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <header>\n        <h1>Mi primera tienda con JavaScript</h1>\n        <p>\n            Vamos a utilizar variables y operadores para\n            calcular el importe de una compra y comprobar\n            si el cliente tiene derecho a descuentos.\n        </p>\n    </header>\n\n    <main>\n        <section>\n            <h2>1. Calcula el precio de la compra</h2>\n\n            <p>Nuestro cliente ha comprado:</p>\n\n            <ul>\n                <li>2 pantalones de 30 € cada uno.</li>\n                <li>1 camiseta de 15 €.</li>\n            </ul>\n\n            <p>\n                Declara las variables necesarias en JavaScript\n                y calcula el importe total de los productos.\n            </p>\n\n            <p class=\"resultado\">\n                El importe de la compra es:\n                <strong><span id=\"total\"></span> €</strong>\n            </p>\n        </section>\n\n        <section>\n            <h2>2. Añade los gastos de envío</h2>\n\n            <p>\n                Nuestra tienda cobra 5 € de gastos de envío\n                por cada pedido.\n            </p>\n\n            <p>\n                Calcula el precio total sumando los gastos\n                de envío al importe de los productos.\n            </p>\n\n            <p class=\"resultado\">\n                El total con gastos de envío es:\n                <strong><span id=\"totalConEnvio\"></span> €</strong>\n            </p>\n        </section>\n\n        <section>\n            <h2>3. Comprueba si tiene descuento</h2>\n\n            <p>\n                Nuestra tienda ofrece un descuento a los\n                clientes que cumplan al menos una de\n                estas condiciones:\n            </p>\n\n            <ul>\n                <li>\n                    El importe de los productos supera los 100 €,\n                    sin contar los gastos de envío.\n                </li>\n                <li>\n                    El cliente compra más de 3 artículos\n                    en total.\n                </li>\n            </ul>\n\n            <p>\n                Utiliza operadores comparativos y lógicos\n                para comprobar si tiene derecho al descuento.\n            </p>\n\n            <p class=\"resultado\">\n                ¿Tiene derecho al descuento?\n                <strong><span id=\"descuento\"></span></strong>\n            </p>\n        </section>\n\n        <section>\n            <h2>4. Comprueba el descuento adicional</h2>\n\n            <p>\n                La tienda ofrece otro descuento especial\n                cuando se cumplen las dos condiciones:\n            </p>\n\n            <ul>\n                <li>\n                    El cliente pertenece al club de fidelidad.\n                </li>\n                <li>\n                    La compra se realiza un viernes.\n                </li>\n            </ul>\n\n            <p>Para esta compra sabemos que:</p>\n\n            <ul>\n                <li>El cliente pertenece al club de fidelidad.</li>\n                <li>Hoy es viernes.</li>\n            </ul>\n\n            <p>\n                Declara las variables booleanas necesarias\n                y comprueba si tiene derecho al descuento.\n            </p>\n\n            <p class=\"resultado\">\n                ¿Tiene derecho al descuento adicional?\n                <strong>\n                    <span id=\"descuentoAdicional\"></span>\n                </strong>\n            </p>\n        </section>\n\n        <section>\n            <h2>5. Comprueba tu programa</h2>\n\n            <p>\n                Crea un archivo llamado script.js y escribe\n                el código necesario para:\n            </p>\n\n            <ol>\n                <li>Declarar las variables.</li>\n                <li>Realizar los cálculos matemáticos.</li>\n                <li>Comprobar las condiciones de descuento.</li>\n                <li>\n                    Mostrar los resultados en los elementos\n                    HTML correspondientes utilizando\n                    getElementById() y textContent.\n                </li>\n                <li>\n                    Comprobar los resultados en la consola\n                    mediante console.log().\n                </li>\n            </ol>\n\n            <p>\n                Los importes deben mostrarse como números\n                y los descuentos como true o false.\n            </p>\n\n            <p>\n                Importante: todavía no tienes que calcular\n                cuánto dinero se descuenta.\n                Solo debes comprobar si el cliente cumple\n                las condiciones de cada promoción.\n            </p>\n        </section>\n        <section>\n            <h2>Para seguir practicando</h2>\n\n            <p>\n                Modifica las cantidades, los precios y los datos del cliente para conseguir que los dos descuentos devuelvan true. Después, cambia únicamente un dato para conseguir que el descuento adicional devuelva false.\n            </p>\n        </section>\n        <section>\n            <h2>6. Comprueba el envío gratuito</h2>\n\n            <p>\n                Comprueba si tu compra tiene derecho a envío gratuito.\n            </p>\n\n            <p class=\"resultado\">\n                <span id=\"envio\"></span>\n            </p>\n        </section>\n    </main>\n</body>\n</html>\n","materiales/js-clases-avante/ejercicio5/styles.css":"\n/* Estilos generales */\n\n:root {\n    --primary-color: #042054;\n    --secondary-color: #db17cb;\n    --background-color: #f3f5f9;\n    --text-color: #273449;\n    --result-background-color: #edf4ff;\n    --result-border-color: #3174c7;\n}\n\n\nbody {\n    margin: 10px auto;\n    padding: 0;\n    font-family: Arial, sans-serif;\n    background-color: var(--background-color);\n    color: var(--text-color);\n    line-height: 1.6;\n    border: 1px solid #253b63;\n    width: 80%;\n    text-align: center;\n}\n\n/* Cabecera */\n\nheader {\n    background-color: var(--primary-color);\n    color: white;\n    text-align: center;\n    padding: 35px 20px;\n    border-bottom: 3px solid var(--secondary-color);\n    border-top: 1px solid var(--secondary-color);\n    text-align: center;\n}\n\nheader h1 {\n    margin: 0 0 10px;\n}\n\nheader p {\n    margin: 0;\n}\n\n/* Contenido principal */\n\nmain {\n    max-width: 850px;\n    margin: 30px auto;\n    padding: 0 20px;\n}\n\n/* Secciones */\n\nsection {\n    background-color: white;\n    padding: 25px;\n    margin-bottom: 20px;\n    border-radius: 10px;\n    border: 1px solid #e0e5ed;\n}\n\nh2 {\n    color: var(--secondary-color);\n    margin-top: 0;\n    font-size: 1.3rem;\n}\n\n/* Listas */\n\nli {\n    margin-bottom: 8px;\n    list-style-type: none;\n}\n\n/* Resultados */\n\n.resultado{\n    background-color: var(--result-background-color);\n    padding: 15px;\n    border-left: 4px solid var(--result-border-color);\n    border-radius: 5px;\n}\n\nspan {\n    font-weight: bold;\n    color: var(--primary-color) ;\n}\n\n/* Adaptación a móviles */\n\n@media (max-width: 600px) {\n    main {\n        margin: 15px auto;\n        padding: 0 12px;\n    }\n\n    section {\n        padding: 18px;\n    }\n\n    header {\n        padding: 25px 15px;\n    }\n}\n","materiales/js-clases-avante/ejercicio6/app.js":"","materiales/js-clases-avante/ejercicio6/ejercicio6.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Practicando operadores</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n    <header>\n        <h1>Mi primera tienda con JavaScript</h1>\n        <p>Vamos a utilizar variables y operadores para calcular el importe de una compra y comprobar si el cliente tiene derecho a descuentos.</p>\n    </header>\n    <main>\n        <section>\n            <h2>1. Calcula el precio de la compra</h2>\n            <p>Nuestro cliente ha comprado:</p>\n            <ul>\n                <li>2 pantalones de 30 € cada uno.</li>\n                <li>1 camiseta de 15 €.</li>\n            </ul>\n            <p>Declara las variables necesarias en JavaScript y calcula el importe total de los productos.</p>\n            <p class=\"resultado\">El importe de la compra es: <strong><span id=\"total\"></span> €</strong></p>\n        </section>\n        <section>\n            <h2>2. Añade los gastos de envío</h2>\n            <p>La tienda cobra 5 € de gastos de envío por cada pedido.</p>\n            <p class=\"resultado\">El total con gastos de envío es: <strong><span id=\"totalConEnvio\"></span> €</strong></p>\n        </section>\n        <section>\n            <h2>3. Comprueba si tiene descuento</h2>\n            <p>Hay descuento si el importe de productos supera 100 € o si compra más de 3 artículos.</p>\n            <p class=\"resultado\">¿Tiene derecho al descuento? <strong><span id=\"descuento\"></span></strong></p>\n        </section>\n        <section>\n            <h2>4. Comprueba el descuento adicional</h2>\n            <p>Hay descuento adicional si pertenece al club de fidelidad y hoy es viernes.</p>\n            <p>Para esta compra, el cliente pertenece al club de fidelidad y hoy es viernes.</p>\n            <p class=\"resultado\">¿Tiene derecho al descuento adicional? <strong><span id=\"descuentoAdicional\"></span></strong></p>\n        </section>\n        <section>\n            <h2>5. Comprueba tu programa</h2>\n            <p>Declara las variables, realiza los cálculos, comprueba las promociones y muestra los resultados con <code>getElementById()</code> y <code>textContent</code>.</p>\n        </section>\n        <section>\n            <h2>Para seguir practicando</h2>\n            <p>Modifica las cantidades, precios y datos del cliente para conseguir que los dos descuentos devuelvan true. Después cambia un dato para que el descuento adicional devuelva false.</p>\n        </section>\n    </main>\n</body>\n</html>","materiales/js-clases-avante/ejercicio6/style.css":"/* Estilos generales */\n:root {\n    --primary-color: #042054;\n    --secondary-color: #db17cb;\n    --background-color: #f3f5f9;\n    --text-color: #273449;\n    --result-background-color: #edf4ff;\n    --result-border-color: #3174c7;\n}\n\nbody {\n    margin: 10px auto;\n    padding: 0;\n    font-family: Arial, sans-serif;\n    background-color: var(--background-color);\n    color: var(--text-color);\n    line-height: 1.6;\n    border: 1px solid #253b63;\n    width: 80%;\n    text-align: center;\n}\n\n/* Cabecera */\nheader {\n    background-color: var(--primary-color);\n    color: white;\n    text-align: center;\n    padding: 35px 20px;\n    border-bottom: 3px solid var(--secondary-color);\n    border-top: 1px solid var(--secondary-color);\n}\n\nheader h1 { margin: 0 0 10px; }\nheader p { margin: 0; }\n\n/* Contenido principal */\nmain {\n    max-width: 850px;\n    margin: 30px auto;\n    padding: 0 20px;\n}\n\n/* Secciones */\nsection {\n    background-color: white;\n    padding: 25px;\n    margin-bottom: 20px;\n    border-radius: 10px;\n    border: 1px solid #e0e5ed;\n}\n\nh2 {\n    color: var(--secondary-color);\n    margin-top: 0;\n    font-size: 1.3rem;\n}\n\n/* Listas */\nli {\n    margin-bottom: 8px;\n    list-style-type: none;\n}\n\n/* Resultados */\n.resultado {\n    background-color: var(--result-background-color);\n    padding: 15px;\n    border-left: 4px solid var(--result-border-color);\n    border-radius: 5px;\n}\n\nspan {\n    font-weight: bold;\n    color: var(--primary-color);\n}\n\n/* Adaptación a móviles */\n@media (max-width: 600px) {\n    main {\n        margin: 15px auto;\n        padding: 0 12px;\n    }\n\n    section { padding: 18px; }\n    header { padding: 25px 15px; }\n}","materiales/js-clases-avante/ejercicio7/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n        let cantidad=100;\n        let precio=100;\n        /*condicion una*/\n        if (cantidad>=5 && precio>0){\n            console.log(\"Tenemos stock con un precio de \" + precio + \" €\");\n            document.getElementById(\"stock\").textContent = \"Tenemos stock con un precio de \" + precio  + \" €\";\n        } \n        /*alternativa al primer if*/\n        else if (cantidad>=5 || (cantidad >0 && precio>0)){\n            console.log(\"Quedan pocas unidades con un precio de \" + precio + \" €\");\n            document.getElementById(\"stock\").textContent = \"Quedan pocas unidades con un precio de \" + precio + \" €\";\n        } \n        /* salida si no cumple ninguna condición */\n        else{\n            console.log(\"No tenemos stock\");\n            document.getElementById(\"stock\").textContent = \"No tenemos stock\";\n        }\r\n","materiales/js-clases-avante/ejercicio7/ejercicio7.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Aprendiendo condicionales</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Aprendiendo condicionales</h1>\n    <h2> ¿Hay stock?</h2>\n    <p><span id=\"stock\"></span></p>\n</body>\n</html>","materiales/js-clases-avante/ejercicio7/styles.css":"","materiales/js-clases-avante/ejercicio8/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/*Crea datos para edad, plazas disponibles, precio \ny si es estudiante. Muestra edad, plazas y precio en HTML.*/\nlet edad = 25;\nlet plazasDisponibles = 10;\nlet precio = 50;\nlet esEstudiante = true;\n\n/*Compara las plazas con 5. Si quedan menos, \nmuestra «¡Últimas plazas!»; en caso contrario, «Plazas disponibles».*/\nif (plazasDisponibles < 5) {\n    console.log(\"¡Últimas plazas!\");\n    document.getElementById(\"plazas\").textContent = \"¡Últimas plazas!\";\n} else  {\n    console.log(\"Plazas disponibles\");\n\n    /*id \"plazas\" del html*/\n    document.getElementById(\"plazas\").textContent = \"Plazas disponibles\";\n\n/*id \"reserva\" del html*/\ndocument.getElementById(\"reserva\").textContent = \"\";\n}\n\n\n\n/*Compara la edad con 18. Muestra si puede o no realizar la reserva.*/\nif (edad >= 18 && plazasDisponibles > 0) {\n    console.log(\"Puede realizar la reserva\");\n    document.getElementById(\"reserva\").textContent = \"Puede realizar la reserva\";\n} else {\n    console.log(\"No puede realizar la reserva\");\n    document.getElementById(\"reserva\").textContent = \"No puede realizar la reserva\";\n}\n\n/*Usa un ternario para elegir entre «Tienes descuento de estudiante» y «Precio estándar».*/\nlet mensaje;\n\nmensaje = esEstudiante ? \"Tienes descuento de estudiante\" : \"Precio estándar\";\ndocument.getElementById(\"precio\").textContent = mensaje;\r\n","materiales/js-clases-avante/ejercicio8/ejercicio8.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Ejercicio de condicionales</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Ejercicio de condicionales</h1>\n    <p>En este ejercicio se muestran las condiciones de plazas disponibles y la edad para realizar la reserva.</p>\n    <p>Puedes hacer la reserva si cumples con los requisitos de edad y disponibilidad de plazas.</p>\n    <p class=\"label\">Plazas disponibles:</p>\n    <p id=\"plazas\"></p>\n    \n    <p id=\"reserva\"></p>\n    \n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio8/styles.css":".label{\n    font-weight: bold;\n    margin-bottom: 5px;\n    font-size: 14px;\n}","materiales/js-clases-avante/ejercicio9/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n/*\n  PRÁCTICA: EVALUADOR DE CALIFICACIONES\n\n  Completa los apartados indicados.\n  Utilizaremos IF, ELSE IF, ELSE y SWITCH.\n\n  La función evaluarNota() ya está preparada.\n  No necesitas modificarla ni entender todavía\n  cómo se crean las funciones.\n*/\n\n\n\n\n\nfunction evaluarNota() {\n  // 1. OBTENER LOS DATOS DEL HTML\n  const nombre = document.getElementById(\"nombre\").value;\n  const notaTexto = document.getElementById(\"nota\").value;\n  const nota = Number(notaTexto);\n\n  // 2. DECLARAR VARIABLES\n  let calificacion = \"\";\n  let mensaje = \"\";\n\n  // 3. COMPROBAR QUE LA NOTA ES VÁLIDA\n  // Esta parte ya está resuelta.\n  if (notaTexto.trim() === \"\" || nota < 0 || nota > 10) {\n    document.getElementById(\"resultado\").textContent =\n      \"Introduce una nota válida entre 0 y 10.\";\n    document.getElementById(\"mensaje\").textContent = \"\";\n    return;\n  }\n\n  // 4. TU TURNO: IF...ELSE IF...ELSE\n if (nota >= 9) {\n    /*calificacion es una variable declarada anteriormente*/\n    calificacion = \"Sobresaliente\";\n  } else if (nota >= 7) {\n    calificacion = \"Notable\";\n  } else if (nota >= 6) {\n    calificacion = \"Bien\";\n  } else if (nota >= 5) {\n    calificacion = \"Suficiente\";\n  } else {\n    calificacion = \"Insuficiente\";\n  }\n\n  // 5. TU TURNO: SWITCH\n/*valoramos la variable que nos devuelve la calificacion*/\n   switch(calificacion) {\n    case \"Sobresaliente\":\n/*mensaje es la variable que contendrá el mensaje correspondiente a la calificación*/\n      mensaje = \"¡Excelente trabajo!\";\n      break;\n    case \"Notable\":\n      mensaje = \"Muy bien, sigue así.\";\n      break;\n    case \"Bien\":\n      mensaje = \"Buen trabajo, pero puedes mejorar.\";\n      break;\n    case \"Suficiente\":\n      mensaje = \"Has aprobado, pero necesitas esforzarte más.\";\n      break;\n    case \"Insuficiente\":\n      mensaje = \"No has aprobado, necesitas estudiar más.\";\n      break;\n    default:\n      mensaje = \"\";\n  }\n\n  // 6. MOSTRAR RESULTADOS EN HTML\n  // Esta parte ya está resuelta.\n  document.getElementById(\"resultado\").textContent =\n    nombre + \", has obtenido un \" + calificacion +\n    \" con una nota de \" + nota + \".\";\n  document.getElementById(\"mensaje\").textContent = mensaje;\n}\r\n","materiales/js-clases-avante/ejercicio9/ejercicio9.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Calculadora de notas</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"app.js\" defer></script>\n</head>\n<body>\n  <h1>Evaluador de calificaciones</h1>\n  <!-- tenemos un input para meter el nombre del alumno -->\n\n  <label for=\"nombre\">Nombre del alumno:</label>\n  <input type=\"text\" id=\"nombre\">\n\n  <label for=\"nota\">Introduce la nota:</label>\n  <input type=\"number\" id=\"nota\" min=\"0\" max=\"10\" step=\"0.1\">\n\n  <button type=\"button\" onclick=\"evaluarNota()\">\n    Evaluar nota\n  </button>\n\n  <h2>Resultado de la evaluación</h2>\n  <p id=\"resultado\"></p>\n\n  <h3>Mensaje para el alumno</h3>\n  <p id=\"mensaje\"></p>\n</body>\n</html>\n    \n</body>\n</html>","materiales/js-clases-avante/ejercicio9/styles.css":"/* Estilos generales */\nbody {\n  font-family: Arial, sans-serif;\n  background-color: #f4f6f9;\n  color: #333;\n  max-width: 500px;\n  margin: 50px auto;\n  padding: 25px;\n  border: 1px solid #ddd;\n  border-radius: 10px;\n}\n\n/* Título */\nh1 {\n  color: #2456a6;\n  text-align: center;\n}\n\n/* Etiquetas */\nlabel {\n  display: block;\n  margin-top: 20px;\n  margin-bottom: 8px;\n  font-weight: bold;\n}\n\n/* Campos de entrada */\ninput {\n  display: block;\n  width: 100%;\n  padding: 10px;\n  border: 1px solid #ccc;\n  border-radius: 5px;\n  box-sizing: border-box;\n}\n\n/* Botón */\nbutton {\n  background-color: #2456a6;\n  color: white;\n  border: none;\n  padding: 12px 20px;\n  margin-top: 25px;\n  border-radius: 5px;\n  cursor: pointer;\n  width: 100%;\n}\n\nbutton:hover {\n  background-color: #173c78;\n}\n\n/* Resultados */\nh2 {\n  margin-top: 30px;\n  color: #2456a6;\n}\n\n#resultado,\n#mensaje {\n  font-weight: bold;\n  color: #2456a6;\n}","materiales/js-clases-avante/funciones/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nfunction comprobarEdad(edad) {\n\n    edad = Number(document.getElementById(\"edad\").value);\n\n    if (edad >= 18) {\n         document.getElementById(\"resultado\").textContent = \"Bienvenido puedes entrar🎉🎉🎉🎉🎉 \";\n    } else {\n         document.getElementById(\"resultado\").textContent = \"No puedes entrar❌❌❌❌❌❌ \";\n    }\n    \n}\r\n","materiales/js-clases-avante/funciones/funciones.html":"\n<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Control de acceso</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n\n    <h1>Control de acceso a la discoteca</h1>\n\n    <img src=\"discoteca.png\" alt=\"Discoteca\">\n\n    <p>Introduce tu edad para comprobar si puedes entrar.</p>\n\n    <label for=\"edad\">¿Cuántos años tienes?</label>\n    <input type=\"number\" id=\"edad\" min=\"0\">\n\n    <button onclick=\"comprobarEdad()\">\n        Comprobar acceso\n    </button>\n\n    <p id=\"resultado\"></p>\n\n</body>\n</html>\n","materiales/js-clases-avante/funciones/styles.css":"body{\n    width:80%;\n    margin: 0 auto;\n    border: 4px solid #131b89;\n    padding: 20px;\n}\nh1{\n    text-align: center;\n    color: #131b89;\n    font-size: 24px;\n}\nbutton{\n    padding: 10px 20px;\n    background-color: #131b89;\n    color: white;\n    border-radius: 5px;\n    cursor: pointer;\n}\n\ninput{\n    border: 2px solid #131b89;\n    border-radius: 5px;\n    padding: 5px;\n}\n\nimg{\n    width:300px;\n    height: auto;\n    border-radius: 10px;\n   \n}","materiales/js-clases-avante/index.html":"<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>JavaScript en clase | Ejercicios</title>\n    <link rel=\"stylesheet\" href=\"styles.css\" />\n  </head>\n  <body>\n    <header class=\"portada\">\n      <p class=\"etiqueta\">CUADERNO DE CLASE · JAVASCRIPT</p>\n      <h1>Teoría, ejercicios y código</h1>\n      <p>\n        Índice de los ejercicios realizados en clase. Abre la actividad para\n        probarla y consulta el HTML o JavaScript para comprenderla.\n      </p>\n      <a class=\"boton\" href=\"#temas\">Ver temas</a>\n    </header>\n    <main>\n      <section class=\"guia\">\n        <div>\n          <p class=\"etiqueta\">CÓMO UTILIZARLO</p>\n          <h2>Una actividad, tres formas de aprender</h2>\n          <ol>\n            <li>Abre la actividad y prueba los datos.</li>\n            <li>\n              Consulta el <strong>HTML</strong> para ver la estructura de la\n              página.\n            </li>\n            <li>Consulta el <strong>JavaScript</strong> para ver la lógica.</li>\n          </ol>\n        </div>\n        <aside>\n          <strong>Nota</strong>\n          <p>\n            Los enlaces de código son copias de consulta. Las actividades\n            originales se mantienen intactas.\n          </p>\n        </aside>\n      </section>\n      <section class=\"teoria\">\n        <p class=\"etiqueta\">RESUMEN RÁPIDO</p>\n        <h2>Conceptos de clase</h2>\n        <div class=\"conceptos\">\n          <div>\n            <h3>Variables</h3>\n            <p>\n              <code>let</code> guarda datos que cambian; <code>const</code>,\n              datos fijos.\n            </p>\n          </div>\n          <div>\n            <h3>Condicionales</h3>\n            <p>\n              <code>if</code>, <code>else</code> y <code>switch</code> toman\n              decisiones.\n            </p>\n          </div>\n          <div>\n            <h3>Bucles</h3>\n            <p><code>while</code> y <code>for</code> repiten instrucciones.</p>\n          </div>\n          <div>\n            <h3>Funciones</h3>\n            <p>Agrupan instrucciones para reutilizarlas.</p>\n          </div>\n        </div>\n      </section>\n      <section id=\"temas\" class=\"temas\">\n        <p class=\"etiqueta\">EJERCICIOS REALIZADOS</p>\n        <h2>Índice por temas</h2>\n        <section class=\"bloque\">\n          <h3><span>01</span> Variables y textos</h3>\n          <p>Declaración de datos, cadenas y salida de información.</p>\n          <div class=\"actividades\">\n            <article>\n              <h4>Ejercicio 1 · Declarar variables</h4>\n              <p>Saludo con nombre, edad y ciudad.</p>\n              <nav>\n                <a href=\"ejercicio1/ejercicio1.html\">Actividad</a\n                ><a href=\"codigo/ejercicio01-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio01-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 2 · Datos de una película</h4>\n              <p>Variables, concatenación y template literals.</p>\n              <nav>\n                <a href=\"ejercicio2/ejercicio2.html\">Actividad</a\n                ><a href=\"codigo/ejercicio02-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio02-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n          </div>\n        </section>\n        <section class=\"bloque\">\n          <h3><span>02</span> Operadores</h3>\n          <p>Operaciones aritméticas, comparación y lógica.</p>\n          <div class=\"actividades\">\n            <article>\n              <h4>Ejercicio 3 · Operadores aritméticos</h4>\n              <p>Precio, cantidad, descuento e IVA.</p>\n              <nav>\n                <a href=\"ejercicio3/ejercicio3.html\">Actividad</a\n                ><a href=\"codigo/ejercicio03-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio03-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 4 · Comparación y lógica</h4>\n              <p>Igualdad, comparación estricta y lógica.</p>\n              <nav>\n                <a href=\"ejercicio4/ejercicio.html\">Actividad</a\n                ><a href=\"codigo/ejercicio04-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio04-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 5 · Tienda</h4>\n              <p>Cálculo de compra, envío y descuentos.</p>\n              <nav>\n                <a href=\"ejercicio5/ejercicio5.html\">Actividad</a\n                ><a href=\"codigo/ejercicio05-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio05-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 6 · Tienda</h4>\n              <p>Interfaz de la práctica de operadores.</p>\n              <nav>\n                <a href=\"ejercicio6/ejercicio6.html\">Actividad</a\n                ><a href=\"codigo/ejercicio06-html.txt\" target=\"_blank\">HTML</a>\n              </nav>\n            </article>\n          </div>\n        </section>\n        <section class=\"bloque\">\n          <h3><span>03</span> Condicionales</h3>\n          <p>\n            Decisiones con <code>if</code>, <code>else if</code>,\n            <code>else</code> y <code>switch</code>.\n          </p>\n          <div class=\"actividades\">\n            <article>\n              <h4>Ejercicio 7 · Stock y precio</h4>\n              <p>Condiciones lógicas.</p>\n              <nav>\n                <a href=\"ejercicio7/ejercicio7.html\">Actividad</a\n                ><a href=\"codigo/ejercicio07-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio07-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 8 · Reserva</h4>\n              <p>Edad, plazas, precio y condición de estudiante.</p>\n              <nav>\n                <a href=\"ejercicio8/ejercicio8.html\">Actividad</a\n                ><a href=\"codigo/ejercicio08-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio08-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 9 · Evaluador de notas</h4>\n              <p>Calificación y mensaje según una nota.</p>\n              <nav>\n                <a href=\"ejercicio9/ejercicio9.html\">Actividad</a\n                ><a href=\"codigo/ejercicio09-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio09-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 10 · Actividad recomendada</h4>\n              <p>Decisión según dinero y buen tiempo.</p>\n              <nav>\n                <a href=\"ejercicio10/ejercicio.html\">Actividad</a\n                ><a href=\"codigo/ejercicio10-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio10-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n          </div>\n        </section>\n        <section class=\"bloque\">\n          <h3><span>04</span> Bucles, funciones y arrays</h3>\n          <p>Repetición, eventos y conjuntos de datos.</p>\n          <div class=\"actividades\">\n            <article>\n              <h4>Ejercicio 11 · Bucles</h4>\n              <p>Repeticiones y control de acceso.</p>\n              <nav>\n                <a href=\"ejercicio11/ejercicio11.html\">Actividad</a\n                ><a href=\"codigo/ejercicio11-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio11-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 12 · Funciones</h4>\n              <p>Funciones llamadas desde botones e inputs.</p>\n              <nav>\n                <a href=\"ejercicio12/ejercicio12.html\">Actividad</a\n                ><a href=\"codigo/ejercicio12-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio12-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 13 · Arrays</h4>\n              <p>Cuaderno de notas y métodos de arrays.</p>\n              <nav>\n                <a href=\"ejercicio13/ejercicio13.html\">Actividad</a\n                ><a href=\"codigo/ejercicio13-html.txt\" target=\"_blank\">HTML</a\n                ><a href=\"codigo/ejercicio13-js.txt\" target=\"_blank\"\n                  >JavaScript</a\n                >\n              </nav>\n            </article>\n            <article>\n              <h4>Ejercicio 14 · Dado</h4>\n              <p>Práctica de funciones, condicionales y arrays.</p>\n              <nav>\n                <a href=\"ejercicio14/dado.html\">Actividad</a\n                ><a href=\"codigo/ejercicio14-html.txt\" target=\"_blank\">HTML</a>\n              </nav>\n            </article>\n          </div>\n        </section>\n      </section>\n    </main>\n    <footer>\n      JavaScript en clase · Índice creado a partir de los ejercicios existentes.\n    </footer>\n  </body>\n</html>\n","materiales/js-clases-avante/local/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * Al iniciar, se recuperan los datos guardados y se actualiza el array. Al añadir un dato: push(), guardar en localStorage y volver a mostrar el listado.\r\n * JSON.stringify convierte arrays u objetos en texto para guardarlos; JSON.parse recupera de nuevo su estructura.\r\n * Los bucles recorren los datos uno a uno. La variable declarada en cada vuelta representa el elemento actual.\r\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los métodos de array se aplican sobre la colección: push añade, find localiza el primer resultado y filter crea una selección.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\nalumnos=[\n    { nombre: \"Juan\", edad: 20 },\n    { nombre: \"María\", edad: 22 },\n    { nombre: \"Pedro\", edad: 21 }\n]\n\n//mostramos los alumnos en el navegador\n\n// Seleccionamos el contenedor una sola vez\nconst listaAlumnos = document.getElementById(\"alumnos\");\n\n\nalumnos = recuperarAlumnos()||alumnos; // Si hay alumnos guardados en el localStorage, los usamos, si no, usamos la lista inicial\n\n// Recorremos el array y mostramos los alumnos\nfor (const alumno of alumnos) {\n   \n  listaAlumnos.innerHTML += `<p>${alumno.nombre} : ${alumno.edad} años</p>`;\n  guardarAlumnos(); // Guardamos los alumnos en el localStorage\n}\n\n\n\n//queremos guardar esta lista de alumnos en el localStorage para que persista aunque cerremos el navegador\n// Guardamos la lista de alumnos en el localStorage\nfunction guardarAlumnos() {\n  // 1. Convertimos el array en texto JSON\n  const alumnosJSON = JSON.stringify(alumnos);\n\n  // 2. Guardamos el texto en localStorage\n  localStorage.setItem(\"alumnosGuardadosLocal\", alumnosJSON);\n}\n//podemos hacerlo mas breve en una sola linea guardamos y convertimos a JSON al mismo tiempo\n//localStorage.setItem(\"alumnos\", JSON.stringify(alumnos));\n\n// Recuperamos la lista de alumnos del localStorage para mostrarla en el navegador\nfunction recuperarAlumnos() {\n  const alumnosGuardados = localStorage.getItem(\"alumnosGuardadosLocal\");\n\n  if (alumnosGuardados) {\n    alumnos = JSON.parse(alumnosGuardados);\n  }\n}\n\n//vamos a crear una función para agregar un nuevo alumno a la lista\nagregarAlumno = () => {\n  const nombre = document.getElementById(\"nombre\").value;\n  const edad = document.getElementById(\"edad\").value;\n\n  if (nombre && edad) {\n    alumnos.push ({nombre,edad});\n    guardarAlumnos();\n    listaAlumnos.innerHTML += `<p>${nombre} : ${edad} años</p>`;\n  } else {\n    alert(\"Por favor, complete todos los campos.\");\n  }\n\n  document.getElementById(\"nombre\").value = \"\";\n  document.getElementById(\"edad\").value = \"\";\n\n}\n\r\n","materiales/js-clases-avante/local/index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Probando local</title>\n    <script src=\"app.js\" defer></script>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n    <h1>Mostrando los alumnos en html</h1>\n\n    <div id=\"alumnos\"></div>\n\n\n    <input type=\"text\" id=\"nombre\" placeholder=\"Nombre del alumno\" required>\n    <input type=\"text\" id=\"edad\" placeholder=\"Edad del alumno\" required>\n    <button type=\"button\" onclick=\"agregarAlumno()\">Agregar Alumno</button>\n    \n</body>\n</html>","materiales/js-clases-avante/local/styles.css":"body{\n    max-width: 600px;\n    background-color: #0b69c6;\n    margin:20px auto;\n    padding: 20px;\n    border-radius: 10px;\n    border: 3px solid #ffffff;\n   \n}\n\nhtml{\n    background-color: #f1f4f6;\n}","materiales/js-clases-avante/notas/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\r\n * Los valores de los inputs son texto. Number() los convierte a número antes de calcular.\r\n * return entrega un resultado desde una función para utilizarlo donde se llamó.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n\n/*\n   PRÁCTICA: EVALUADOR DE CALIFICACIONES\n\n   Completa los apartados indicados.\n   Utilizaremos IF, ELSE IF, ELSE y SWITCH.\n\n   IMPORTANTE:\n   La función evaluarNota() ya está preparada.\n   No necesitas modificarla ni entender todavía\n   cómo se crean las funciones.\n\n   Escribe tu código dentro de los apartados\n   señalados.\n*/\n\nfunction evaluarNota() {\n\n    // ========================================\n    // 1. OBTENER LOS DATOS DEL HTML\n    // ========================================\n\n    const nombre = document.getElementById(\"nombre\").value;\n\n    const notaTexto = document.getElementById(\"nota\").value;\n    const nota = Number(notaTexto);\n\n\n    // ========================================\n    // 2. DECLARAR VARIABLES\n    // ========================================\n\n    let calificacion = \"\";\n    let mensaje = \"\";\n\n\n    // ========================================\n    // 3. COMPROBAR QUE LA NOTA ES VÁLIDA\n    // Esta parte ya está resuelta.\n    // ========================================\n\n    if (notaTexto.trim() === \"\" || nota < 0 || nota > 10) {\n\n        document.getElementById(\"resultado\").textContent =\n            \"Introduce una nota válida entre 0 y 10.\";\n\n        document.getElementById(\"mensaje\").textContent = \"\";\n\n        return;\n    } /*fin de la funcion*/\n\n\n    // ========================================\n    // 4. TU TURNO: IF...ELSE IF...ELSE\n    // ========================================\n\n    /*\n       Determina la calificación del alumno:\n\n       Menos de 5     → Suspenso\n       Desde 5 a < 6  → Suficiente\n       Desde 6 a < 7  → Bien\n       Desde 7 a < 9  → Notable\n       Desde 9 a 10   → Sobresaliente\n\n       Guarda el resultado en la variable\n       calificacion que ya esta declarada. No la declares sólo evalua su nota. La nota te vendrá del HTML.\n\n       Utiliza if, else if y else.\n    */\n\n  \n\n\n\n\n\n    // ========================================\n    // 5. TU TURNO: SWITCH\n    // ========================================\n\n    /*\n       Según el valor de calificacion,\n       guarda en la variable mensaje:\n\n       Suspenso:\n       \"Necesitas seguir practicando.\"\n\n       Suficiente:\n       \"Has conseguido aprobar.\"\n\n       Bien:\n       \"Buen trabajo.\"\n\n       Notable:\n       \"Muy buen resultado.\"\n\n       Sobresaliente:\n       \"Excelente trabajo.\"\n\n       Utiliza switch, case, break y default.\n    */\n\n    // ESCRIBE AQUÍ TU CÓDIGO\n    \n\n\n\n\n\n    // ========================================\n    // 6. MOSTRAR RESULTADOS EN HTML\n    // Esta parte ya está resuelta. Esta vez quiero que te concentres en la lógica de calificación y mensaje.\n    // ========================================\n\n    document.getElementById(\"resultado\").textContent =\n        nombre + \", has obtenido un \" + calificacion +\n        \" con una nota de \" + nota + \".\";\n\n    document.getElementById(\"mensaje\").textContent = mensaje;\n\n}\n\r\n","materiales/js-clases-avante/notas/notas.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Calculadora de notas</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n    <script src=\"app.js\" defer></script>\n</head>\n<body>\n    <h1>Evaluador de calificaciones</h1>\n\n<label for=\"nombre\">Nombre del alumno:</label>\n<input type=\"text\" id=\"nombre\">\n\n<label for=\"nota\">Introduce la nota:</label>\n<input type=\"number\" id=\"nota\" min=\"0\" max=\"10\" step=\"0.1\">\n\n\n<button type=\"button\" onclick=\"evaluarNota()\">\n    Evaluar nota\n</button>\n\n<h2>Resultado de la evaluación</h2>\n\n<p id=\"resultado\"></p>\n\n<h3>Mensaje para el alumno</h3>\n<p id=\"mensaje\"></p>\n\n\n\n\n</body>\n</html>","materiales/js-clases-avante/notas/styles.css":"\n/* Estilos generales */\nbody {\n    font-family: Arial, sans-serif;\n    background-color: #f4f6f9;\n    color: #333;\n    max-width: 500px;\n    margin: 50px auto;\n    padding: 25px;\n    border: 1px solid #ddd;\n    border-radius: 10px;\n}\n\n/* Título */\nh1 {\n    color: #2456a6;\n    text-align: center;\n}\n\n/* Etiquetas */\nlabel {\n    display: block;\n    margin-top: 20px;\n    margin-bottom: 8px;\n    font-weight: bold;\n}\n\n/* Campos de entrada */\ninput {\n    display: block;\n    width: 100%;\n    padding: 10px;\n    border: 1px solid #ccc;\n    border-radius: 5px;\n    box-sizing: border-box;\n}\n\n/* Botón */\nbutton {\n    background-color: #2456a6;\n    color: white;\n    border: none;\n    padding: 12px 20px;\n    margin-top: 25px;\n    border-radius: 5px;\n    cursor: pointer;\n    width: 100%;\n}\n\n/* Botón al pasar el ratón */\nbutton:hover {\n    background-color: #173c78;\n}\n\n/* Resultados */\nh2 {\n    margin-top: 30px;\n    color: #2456a6;\n}\n\n#resultado,\n#mensaje {\n    font-weight: bold;\n    color: #2456a6;\n}\n","materiales/js-clases-avante/styles.css":":root {\n  --tinta: #101820;\n  --amarillo: #d6d60b;\n  --fondo: #f8fafc;\n  --papel: #fff;\n  --texto: #30343a;\n  --enlace: #0b62c4;\n  --borde: #d1d5db;\n}\n* {\n  box-sizing: border-box;\n}\nhtml {\n  scroll-behavior: smooth;\n}\nbody {\n  margin: 0;\n  color: var(--texto);\n  background: var(--fondo);\n  font:\n    16px/1.65 Arial,\n    Helvetica,\n    sans-serif;\n}\n.portada {\n  padding: 6rem max(7vw, 2rem) 5rem;\n  color: #fff;\n  background: var(--tinta);\n}\n.etiqueta {\n  margin: 0 0 0.6rem;\n  color: #6f7100;\n  font-size: 0.75rem;\n  font-weight: 800;\n  letter-spacing: 0.13em;\n}\n.portada .etiqueta {\n  color: var(--amarillo);\n}\nh1,\nh2,\nh3,\nh4 {\n  color: var(--tinta);\n  line-height: 1.2;\n}\nh1 {\n  max-width: 800px;\n  margin: 0 0 0.7rem;\n  color: #fff;\n  font-size: clamp(2.7rem, 6vw, 5.3rem);\n  letter-spacing: -0.05em;\n}\nh2 {\n  margin: 0 0 1.2rem;\n  font-size: clamp(1.9rem, 3vw, 2.7rem);\n}\nh3 {\n  margin: 0;\n  font-size: 1.55rem;\n}\nh4 {\n  margin: 0 0 0.4rem;\n  font-size: 1.05rem;\n}\n.portada > p:not(.etiqueta) {\n  max-width: 680px;\n  font-size: 1.2rem;\n}\n.boton {\n  display: inline-block;\n  margin-top: 1rem;\n  padding: 0.7rem 1rem;\n  color: var(--tinta);\n  background: var(--amarillo);\n  font-weight: 700;\n  text-decoration: none;\n}\nmain {\n  width: min(1120px, 88%);\n  margin: auto;\n}\n.guia {\n  display: grid;\n  grid-template-columns: 1.4fr 0.75fr;\n  gap: 3rem;\n  padding: 4.5rem 0;\n}\nol {\n  padding-left: 1.3rem;\n}\n.guia aside {\n  align-self: center;\n  padding: 1.4rem;\n  background: #fff9d7;\n  border-left: 5px solid var(--amarillo);\n}\n.guia aside p {\n  margin-bottom: 0;\n}\n.teoria {\n  padding: 3.5rem 0;\n  border-top: 1px solid var(--borde);\n}\n.conceptos {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 1rem;\n}\n.conceptos > div {\n  padding: 1.2rem;\n  background: var(--papel);\n  border-top: 4px solid var(--amarillo);\n}\n.conceptos p {\n  margin-bottom: 0;\n}\ncode {\n  padding: 0.1rem 0.3rem;\n  color: #a21c50;\n  background: #eef0f3;\n  border-radius: 3px;\n  font-family: Consolas, monospace;\n  font-size: 0.9em;\n}\n.temas {\n  padding: 4.5rem 0;\n}\n.bloque {\n  padding: 2.2rem 0;\n  border-top: 1px solid var(--borde);\n}\n.bloque > h3 {\n  display: flex;\n  align-items: center;\n  gap: 0.8rem;\n}\n.bloque > h3 span {\n  color: var(--enlace);\n  font-size: 1rem;\n}\n.bloque > p {\n  margin: 0.6rem 0 1.2rem;\n}\n.actividades {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 1rem;\n}\narticle {\n  padding: 1.2rem;\n  background: var(--papel);\n  border: 1px solid var(--borde);\n}\narticle p {\n  min-height: 3.2rem;\n  margin: 0 0 0.9rem;\n}\nnav {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.45rem;\n}\nnav a {\n  padding: 0.42rem 0.55rem;\n  color: var(--enlace);\n  background: #e9f3ff;\n  border-radius: 3px;\n  font-size: 0.85rem;\n  font-weight: 700;\n  text-decoration: none;\n}\nnav a:hover,\nnav a:focus {\n  color: #fff;\n  background: var(--enlace);\n}\nfooter {\n  padding: 2rem;\n  color: #dfe8ee;\n  background: #1e293b;\n  text-align: center;\n}\n@media (max-width: 760px) {\n  .portada {\n    padding: 4rem 2rem;\n  }\n  .guia {\n    grid-template-columns: 1fr;\n    gap: 1.5rem;\n    padding: 3rem 0;\n  }\n  .conceptos,\n  .actividades {\n    grid-template-columns: 1fr;\n  }\n  .teoria,\n  .temas {\n    padding: 3rem 0;\n  }\n}\n","materiales/js-clases-avante/variables/app.js":"/*\n * REVISIÓN DIDÁCTICA DEL CUADERNO\n *\n * Esta es la solución trabajada en clase, conservada con sus nombres originales.\n * Ideas clave de esta práctica:\n * textContent escribe texto seguro; innerHTML se utiliza aquí para crear la estructura HTML dinámica del ejercicio.\r\n * Primero se seleccionan los elementos del HTML; después las funciones cambian su contenido o leen sus valores.\n *\n * Estudia cada bloque, modifica un dato y observa qué parte de la página cambia.\n */\n// let se utiliza cuando el valor puede cambiar.\nlet nombre = \"Ana\";\nlet edad = 18;\n\n// const se utiliza cuando el valor no cambiará.\nconst ciudad = \"Madrid\";\nconst curso = \"JavaScript\";\n\ndocument.getElementById(\"nombre\").textContent = nombre;\ndocument.getElementById(\"edad\").textContent = edad;\ndocument.getElementById(\"ciudad\").textContent = ciudad;\ndocument.getElementById(\"curso\").textContent = curso;\ndocument.getElementById(\"mensaje\").textContent = `¡Hola, ${nombre}! Tienes ${edad} años y estás aprendiendo ${curso}.`;\n\n// Parte 2: prompt permite pedir un dato al usuario.\nconst nombreUsuario = prompt(\"¿Cómo te llamas?\");\nconst saludo = document.getElementById(\"saludo\");\n\nif (nombreUsuario && nombreUsuario.trim()) {\n  saludo.textContent = `¡Encantado de conocerte, ${nombreUsuario.trim()}!`;\n} else {\n  saludo.textContent = \"No has escrito ningún nombre.\";\n}\n\n/*\n// Parte 3: leemos el valor escrito en cada input.\nconst formulario = document.getElementById(\"formulario-datos\");\nconst resultadoFormulario = document.getElementById(\"resultado-formulario\");\n\nformulario.addEventListener(\"submit\", (evento) => {\n  evento.preventDefault();\n\n  const nombreInput = document.getElementById(\"nombre-input\").value;\n  const edadInput = document.getElementById(\"edad-input\").value;\n  const ciudadInput = document.getElementById(\"ciudad-input\").value;\n\n  resultadoFormulario.textContent = `Te llamas ${nombreInput}, tienes ${edadInput} años y vives en ${ciudadInput}.`;\n});\n*/\n\r\n","materiales/js-clases-avante/variables/ejercicio1.html":"<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Actividad 1 | Variables</title>\n    <link rel=\"stylesheet\" href=\"style.css\">\n    <script src=\"app.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <a class=\"volver\" href=\"../index.html\">← Volver a la portada</a>\n      <h1>Actividad 1: Declarar variables</h1>\n      <p class=\"intro\">En esta actividad usamos <code>let</code> para datos que pueden cambiar y <code>const</code> para los que permanecen fijos.</p>\n\n      <section>\n        <h2>Mis datos</h2>\n        <p>Nombre: <span id=\"nombre\"></span></p>\n        <p>Edad: <span id=\"edad\"></span> años</p>\n        <p>Ciudad: <span id=\"ciudad\"></span></p>\n        <p>Curso: <span id=\"curso\"></span></p>\n      </section>\n\n      <p id=\"mensaje\" aria-live=\"polite\"></p>\n\n      <section>\n        <h2>Parte 2: Usar prompt</h2>\n        <p>Escribe tu nombre en la ventana que aparece.</p>\n        <p id=\"saludo\" aria-live=\"polite\"></p>\n      </section>\n\n      <!--\n      <section>\n        <h2>Parte 3: Usar inputs</h2>\n        <p>Completa tus datos y pulsa el botón.</p>\n\n        <form id=\"formulario-datos\">\n          <label for=\"nombre-input\">Nombre</label>\n          <input id=\"nombre-input\" type=\"text\" required>\n\n          <label for=\"edad-input\">Edad</label>\n          <input id=\"edad-input\" type=\"number\" min=\"1\" required>\n\n          <label for=\"ciudad-input\">Ciudad</label>\n          <input id=\"ciudad-input\" type=\"text\" required>\n\n          <button type=\"submit\">Mostrar mis datos</button>\n        </form>\n\n        <p id=\"resultado-formulario\" aria-live=\"polite\"></p>\n      </section>\n      -->\n    </main>\n  </body>\n</html>\n","materiales/js-clases-avante/variables/style.css":"body {\n    font-family: Arial, sans-serif;\n    margin: 0;\n    min-height: 100vh;\n    display: grid;\n    place-items: center;\n    background: #f7df1e;\n}\n\nmain {\n    width: min(90%, 500px);\n    padding: 32px;\n    text-align: center;\n    background-color: white;\n    border-radius: 12px;\n    box-shadow: 0 8px 20px rgba(0, 0, 0, .14);\n}\n\n.intro {\n    line-height: 1.5;\n}\n\nsection {\n    margin: 24px 0;\n    padding: 16px;\n    text-align: left;\n    background: #fff8d8;\n    border-radius: 8px;\n}\n\n/* Estilos de la parte 3: formulario con inputs.\nform {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    text-align: left;\n}\n\ninput,\nbutton {\n    padding: 10px;\n    font: inherit;\n    border-radius: 6px;\n}\n\ninput {\n    border: 1px solid #aaa;\n}\n\nbutton {\n    margin-top: 8px;\n    color: #fff;\n    cursor: pointer;\n    background: #0056b3;\n    border: 0;\n}\n\n#resultado-formulario {\n    margin-bottom: 0;\n    font-weight: bold;\n}\n*/\n\n#mensaje {\n    font-size: 1.2rem;\n    margin: 24px 0;\n    font-weight: bold;\n}\n\n.volver {\n    color: #0056b3;\n    display: inline-block;\n    margin-bottom: 12px;\n}\n"};
